/* 01. GLOBAL VARIABLES & FONTS */
:root {
  --maroon: #800000;
  --maroon-dark: #800000;
  --ink: #10243a;
  --green: #4e555c;
  --cream: #fbf8f2;
  --gold: #ddb47a;
  --line: #e9e2d8
}


/* 02. GLOBAL RESET & TYPOGRAPHY */
* {
  box-sizing: border-box
}

body {
  font-family: 'DM Sans', Arial, sans-serif;
  color: #293845;
  margin: 0;
  background: #fff
}

h1,
h2,
h3,
.brand-type {
  font-family: 'Libre Baskerville', Georgia, serif;
  color: var(--ink);
  letter-spacing: -.035em
}

a {
  text-decoration: none
}

/* Ensure FontAwesome solid icons always render with weight 900 */
.fa-solid, .fas {
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 900 !important;
}

.fa-regular, .far {
  font-family: "Font Awesome 6 Free" !important;
  font-weight: 400 !important;
}

.fa-brands, .fab {
  font-family: "Font Awesome 6 Brands" !important;
  font-weight: 400 !important;
}

/* Paragraph inline links — theme maroon */
p a {
  color: var(--maroon);
  text-decoration: underline;
  text-underline-offset: 2px;
  text-decoration-thickness: 1px;
  font-weight: 500;
}

p a:hover {
  color: var(--maroon-dark);
  text-decoration-thickness: 2px;
}

p {
  line-height: 1.7
}

button,
a {
  transition: all .25s ease
}

.container {
  max-width: 1320px
}


/* 03. HEADER & NAVIGATION */
.topbar {
  height: 26px;
  background: #800000;
  color: #fff;
  font-size: 10px;
  letter-spacing: .16em;
  font-weight: 700;
  display: flex;
  align-items: center
}

.topbar a {
  color: #fff
}

.main-nav {
  background: #fff;
  min-height: 83px;
  box-shadow: 0 2px 18px #18231c0c;
  position: sticky;
  top: 0;
  z-index: 1100 !important;
}

.navbar-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-right: 24px
}

.site-brand {
  padding-top: 4px;
  padding-bottom: 4px;
}

.site-logo {
  display: block;
  width: auto;
  height: auto;
  object-fit: contain;
}

.site-logo--header {
  height: 56px;
  width: auto;
  max-width: min(280px, 58vw);
}

.site-logo--footer {
  height: 64px;
  width: auto;
  max-width: 300px;
}

.brand-mark {
  position: relative;
  isolation: isolate;
  height: 54px;
  width: 54px;
  flex: 0 0 54px;
  border-radius: 4px;
  background: var(--maroon);
  color: transparent;
  font-size: 0;
  line-height: 0;
  overflow: hidden;
  display: block;
}

.brand-mark::before {
  content: "\FDFD";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -54%) scale(0.2);
  transform-origin: center;
  font-size: 86px;
  font-family: "Amiri", "Noto Naskh Arabic", "Traditional Arabic", "Scheherazade New", "Times New Roman", serif;
  font-weight: 400;
  color: #ffffff;
  line-height: 1;
  white-space: nowrap;
  pointer-events: none;
}

.brand-type {
  position: relative;
  z-index: 1;
  font-size: 17px;
  line-height: 1.16;
  color: var(--maroon-dark);
  font-weight: 400;
  letter-spacing: -.03em
}

.brand-type b {
  font-weight: 700
}

.brand-type small {
  display: block;
  font: 700 7px 'DM Sans', sans-serif;
  letter-spacing: .18em;
  color: #526071;
  margin-top: 5px
}

.nav-link {
  font-size: 12px;
  font-weight: 700;
  color: #14293e !important;
  padding: 15px 12px !important
}

.nav-link:hover,
.dropdown-item:hover {
  color: var(--maroon) !important
}

.dropdown-menu {
  border: 1px solid var(--line);
  box-shadow: 0 20px 45px #061c201a;
  border-radius: 0
}

.dropdown-item {
  font-size: 12px;
  padding: 10px 18px
}

.btn {
  border-radius: 1px;
  font-size: 10px;
  letter-spacing: .11em;
  font-weight: 800;
  padding: 13px 21px;
  line-height: 1.5
}

.btn:hover {
  transform: translateY(-2px)
}

.btn-burgundy {
  background: var(--maroon);
  color: #fff;
  border: 1px solid var(--maroon)
}

.btn-burgundy:hover {
  background: var(--maroon-dark);
  border-color: var(--maroon-dark);
  color: #fff
}

.btn-outline-burgundy {
  color: var(--maroon);
  border: 1px solid var(--maroon);
  background: #ffffffc4
}

.btn-outline-burgundy:hover {
  background: var(--maroon);
  color: #fff
}

.hero {
  min-height: 475px;
  background-color: #f9f6ef;
  background-image: linear-gradient(90deg, #fcfaf7 0%, #fcfaf7 26%, #fcfaf7ee 35%, #fcfaf755 50%, transparent 67%), var(--hero-image);
  background-position: center, right center;
  background-size: cover, 65% auto;
  background-repeat: no-repeat;
  position: relative
}

.hero:before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: radial-gradient(circle at 0 30%, #d9b78429 0 1px, transparent 1.5px);
  background-size: 18px 18px;
  mask-image: linear-gradient(90deg, #000, transparent 35%)
}

.hero-inner {
  min-height: 475px;
  position: relative;
  display: flex;
  align-items: center
}

.hero-copy {
  width: 50%;
  position: relative;
  z-index: 1;
  padding: 45px 0
}

.section-eyebrow {
  font: 800 10px 'DM Sans', sans-serif;
  color: var(--maroon);
  letter-spacing: .17em;
  text-transform: uppercase;
  margin-bottom: 12px
}

.hero h1 {
  font-size: clamp(37px, 4.4vw, 62px);
  line-height: 1.14;
  margin: 0 0 17px
}

.hero h1 em,
.feature-section h2 em {
  font-weight: 400;
  color: var(--maroon)
}

.hero-copy>p {
  max-width: 440px;
  font-size: 14px;
  line-height: 1.68;
  color: #334052;
  margin-bottom: 23px
}

.hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px
}

.hero-quote {
  position: absolute;
  right: 0;
  bottom: 0;
  background: #4a5158e8;
  color: #fff;
  padding: 29px 31px 32px;
  font: italic 21px/1.43 'Libre Baskerville', Georgia, serif;
  min-width: 248px;
  box-shadow: inset 0 4px var(--gold)
}

.values-strip {
  background: #fff;
  border-block: 1px solid var(--line)
}

.value-item {
  text-align: center;
  display: block;
  padding: 25px 12px 21px;
  color: #46515c;
  border-right: 1px solid var(--line);
  height: 100%
}

.value-item:hover {
  background: #fdf7f4
}

.value-item i {
  font-size: 27px;
  color: var(--maroon);
  margin-bottom: 12px
}

.value-item h3 {
  font-size: 14px;
  color: var(--maroon);
  letter-spacing: -.02em;
  margin: 0 0 7px
}

.value-item p {
  font-size: 11px;
  line-height: 1.4;
  max-width: 160px;
  margin: auto
}

.feature-section {
  padding: 48px 0 52px;
  background: #fdfcf9
}

.feature-image {
  position: relative;
  min-height: 320px;
  overflow: hidden
}

.feature-image img {
  width: 100%;
  height: 340px;
  object-fit: cover
}

.image-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  background: #860b32ed;
  color: #fff;
  font: italic 22px Georgia, serif;
  padding: 17px 25px
}

.feature-section h2 {
  font-size: clamp(31px, 3.3vw, 47px);
  line-height: 1.19;
  margin-bottom: 18px
}

.feature-section p {
  font-size: 14px;
  max-width: 520px;
  color: #4a525f;
  margin-bottom: 22px
}

.section-pad {
  padding: 52px 0 58px
}

.soft {
  background: var(--cream)
}

.section-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 22px;
  gap: 15px
}

.section-head h2,
.display-title {
  font-size: clamp(27px, 3vw, 41px);
  margin: 0;
  line-height: 1.2
}

.text-link {
  font-size: 10px;
  font-weight: 800;
  letter-spacing: .09em;
  color: var(--maroon)
}

.text-link i {
  margin-left: 6px
}

.text-link:hover {
  color: #800000
}

.content-card {
  background: #fff;
  border: 1px solid var(--line);
  overflow: hidden;
  transition: box-shadow .2s ease, transform .2s ease
}

.content-card:hover {
  box-shadow: 0 14px 30px #152b321c;
  transform: translateY(-4px)
}

.card-photo {
  width: 100%;
  height: 160px;
  display: block;
  object-fit: cover
}

.card-content {
  padding: 18px 19px 20px;
  position: relative
}

.round-icon {
  width: 45px;
  height: 45px;
  border-radius: 50%;
  background: var(--maroon);
  display: grid;
  place-items: center;
  color: white;
  margin-top: -44px;
  margin-bottom: 13px;
  position: relative;
  border: 4px solid white;
  font-size: 16px
}

.content-card h3 {
  font-size: 17px;
  line-height: 1.4;
  color: var(--maroon-dark);
  margin-bottom: 9px
}

.content-card p {
  font-size: 12px;
  line-height: 1.55;
  color: #5c626a;
  min-height: 55px;
  margin: 0 0 13px
}

.resource-search {
  padding: 28px 0
}

.search-panel {
  padding: 26px 30px;
  background: #f3efe9
}

.search-panel h2 {
  font-size: 24px;
  margin: 0 0 15px
}

.search-panel p {
  font-size: 11px
}

.search-panel input {
  border-radius: 0;
  padding: 12px 16px;
  border: 1px solid #ddd6cd
}

.platforms {
  display: flex;
  gap: 9px;
  flex-wrap: wrap
}

.platforms a {
  padding: 12px;
  background: white;
  border: 1px solid var(--line);
  font-size: 12px;
  color: var(--maroon)
}

.platforms i {
  font-size: 18px;
  margin-right: 5px
}

.partner-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 8px;
  margin-top: 22px
}

.partner-grid span {
  display: grid;
  place-items: center;
  background: white;
  border: 1px solid var(--line);
  min-height: 95px;
  font-family: Georgia, serif;
  color: #606870;
  font-weight: bold;
  text-align: center;
  padding: 12px
}

.cta-band {
  padding: 39px 0;
  background: linear-gradient(115deg, #424950, #5e666e 70%, #444b52);
  color: #fff
}

.cta-band .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 22px
}

.cta-band h2 {
  font-size: clamp(25px, 3.3vw, 43px);
  line-height: 1.28;
  color: white
}

.cta-band p {
  font-size: 12px;
  max-width: 610px;
  margin: 13px 0 0
}

.gold {
  color: #e7be75
}

.cta-actions {
  display: flex;
  gap: 8px;
  flex-shrink: 0
}

.btn-outline-light {
  border: 1px solid #ffffff80;
  color: #fff
}

.site-footer {
  background: var(--maroon-dark);
  color: white;
  padding: 30px 0 13px
}

.footer-brand {
  font: 20px/1.2 Georgia, serif;
  color: #fff
}

.site-footer p {
  font-size: 11px;
  color: #f2d8dc;
  margin: 12px 0 0
}

.footer-links {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px
}

.footer-links a {
  color: #f8eced;
  font-size: 11px
}

.footer-links a:hover {
  text-decoration: underline
}

.social {
  display: flex;
  gap: 12px;
  justify-content: end
}

.social a {
  height: 28px;
  width: 28px;
  border-radius: 50%;
  background: white;
  display: grid;
  place-items: center;
  color: var(--maroon-dark);
  font-size: 13px
}

.footer-bottom {
  font-size: 9px;
  border-top: 1px solid #ffffff40;
  margin-top: 26px;
  padding-top: 15px;
  color: #eacfd4;
  display: flex;
  justify-content: space-between
}

.footer-bottom a {
  color: white
}

.donation-box {
  background: white;
  max-width: 600px;
  padding: 30px;
  margin: 25px auto 0;
  border: 1px solid var(--line)
}

.donation-amounts {
  display: flex;
  gap: 9px;
  flex-wrap: wrap;
  justify-content: center
}

.amount-btn {
  border: 1px solid #ddd;
  background: #faf9f7;
  padding: 17px 24px;
  font-size: 17px;
  color: var(--ink)
}

.amount-btn.selected,
.amount-btn:hover {
  background: var(--maroon);
  border-color: var(--maroon);
  color: white
}

@media(max-width:1199px) {
  .nav-link {
    padding: 12px 7px !important;
    font-size: 11px
  }

  .brand-type {
    font-size: 14px
  }

  .brand-mark {
    width: 46px;
    height: 46px;
    flex-basis: 46px
  }

  .hero {
    background-size: cover, 77% auto
  }

  .hero-copy {
    width: 55%
  }

  .hero-quote {
    font-size: 17px;
    min-width: 200px
  }

  .cta-band .container {
    align-items: start;
    flex-direction: column
  }
}

@media(max-width:991px) {
  .main-nav {
    min-height: 72px
  }

  .navbar-collapse {
    padding: 15px;
    background: white
  }

  .nav-link {
    padding: 10px !important
  }

  .hero,
  .hero-inner {
    min-height: 460px
  }

  .hero {
    background-image: linear-gradient(90deg, #fcfaf7 0%, #fcfaf7ef 34%, #fcfaf7a0 55%, #ffffff08 100%), var(--hero-image);
    background-size: cover, cover
  }

  .hero-copy {
    width: 67%
  }

  .feature-image img {
    height: 330px
  }

  .footer-links {
    grid-template-columns: repeat(3, 1fr)
  }

  .social {
    justify-content: start
  }
}

@media(max-width:767px) {
  .topbar {
    font-size: 8px;
    letter-spacing: .08em
  }

  .hero,
  .hero-inner {
    min-height: 560px
  }

  .hero {
    background-image: linear-gradient(0deg, #fcfaf7 0%, #fcfaf7f4 26%, #fcfaf79c 64%, #ffffff00 100%), var(--hero-image);
    background-size: cover, auto 65%;
    background-position: center, top right
  }

  .hero-inner {
    align-items: flex-end
  }

  .hero-copy {
    width: 100%;
    padding: 185px 0 35px
  }

  .hero h1 {
    font-size: clamp(33px, 8vw, 48px)
  }

  .hero-copy>p {
    font-size: 12px;
    max-width: 95%
  }

  .hero-quote {
    display: none
  }

  .hero-actions {
    gap: 7px
  }

  .hero-actions .btn {
    padding: 11px;
    font-size: 9px
  }

  .value-item {
    border-bottom: 1px solid var(--line)
  }

  .feature-section,
  .section-pad {
    padding: 32px 0
  }

  .section-head h2 {
    font-size: 29px
  }

  .card-photo {
    height: 145px
  }

  .cta-actions {
    flex-wrap: wrap
  }

  .partner-grid {
    grid-template-columns: repeat(2, 1fr)
  }

  .footer-links {
    grid-template-columns: repeat(2, 1fr)
  }

  .footer-bottom {
    gap: 12px;
    flex-wrap: wrap
  }

  .feature-image {
    min-height: 230px
  }

  .feature-image img {
    height: 250px
  }

  .image-caption {
    font-size: 17px
  }

  .feature-section h2 {
    font-size: 30px
  }

  .topbar .container {
    gap: 4px
  }

  .cta-band h2 br {
    display: none
  }
}

@media(prefers-reduced-motion:reduce) {

  *,
  *:before,
  *:after {
    transition: none !important;
    scroll-behavior: auto !important
  }
}

/* 06. HOMEPAGE */
/* ==========================================================================
   HOMEPAGE SCREENSHOT REPLICA STYLES
   ========================================================================== */

/* Topbar enhancements */
.topbar-search-icon {
  font-size: 11px;
  margin-left: 8px;
  cursor: pointer;
}

/* Eyebrows with inline line */
.eyebrow-container {
  display: inline-flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 12px;
}

.eyebrow-text {
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #800000;
}

.eyebrow-gold {
  color: #deb87b !important;
}

.eyebrow-line {
  display: inline-block;
  width: 42px;
  height: 2px;
  background-color: #800000;
}

.hero-eyebrow-text {
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: #8f795d;
  margin-bottom: 16px;
}

/* Button variants matching design */
.btn-solid-maroon {
  background-color: #800000;
  border: 1px solid #800000;
  color: #ffffff !important;
  font-family: 'DM Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 13px 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 1px;
  text-decoration: none;
  transition: all 0.25s ease;
}

.btn-solid-maroon:hover {
  background-color: #800000;
  border-color: #800000;
  color: #ffffff;
  transform: translateY(-2px);
}

.btn-outline-bordered {
  background-color: #ffffff;
  border: 1px solid #4a5765;
  color: #10243a !important;
  font-family: 'DM Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 13px 22px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: 1px;
  text-decoration: none;
  transition: all 0.25s ease;
}

.btn-outline-bordered:hover {
  background-color: #f7f4ed;
  border-color: #10243a;
  transform: translateY(-2px);
}

.btn-white-pill {
  background-color: #ffffff;
  color: #800000 !important;
  font-family: 'DM Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 12px 24px;
  border-radius: 2px;
  display: inline-flex;
  align-items: center;
  border: none;
  text-decoration: none;
  transition: all 0.25s ease;
}

.btn-white-pill:hover {
  background-color: #fdf5f7;
  color: #800000 !important;
  transform: translateY(-2px);
}

.btn-outline-trans-white {
  background-color: transparent;
  border: 1px solid rgba(255, 255, 255, 0.45);
  color: #ffffff !important;
  font-family: 'DM Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.09em;
  text-transform: uppercase;
  padding: 13px 24px;
  display: inline-flex;
  align-items: center;
  border-radius: 1px;
  text-decoration: none;
  transition: all 0.25s ease;
}

.btn-outline-trans-white:hover {
  background-color: rgba(255, 255, 255, 0.1);
  border-color: #ffffff;
  transform: translateY(-2px);
}

/* HERO SECTION */
.hero-replica {
  background-color: #fcfbf8;
  position: relative;
  overflow: hidden;
  border-bottom: 1px solid #eee7dd;
}

.hero-replica .container {
  padding-top: 15px;
  padding-bottom: 0;
}

.hero-text-side {
  padding: 50px 35px 60px 0;
}

.hero-replica-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(38px, 4.3vw, 56px);
  line-height: 1.15;
  color: #10243a;
  margin-bottom: 18px;
  font-weight: 700;
}

.hero-replica-title em {
  font-style: italic;
  font-weight: 400;
  color: #800000;
}

.hero-replica-desc {
  font-size: 15px;
  line-height: 1.68;
  color: #3e4a57;
  max-width: 480px;
  margin-bottom: 28px;
}

.hero-replica-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.hero-image-side {
  position: relative;
  min-height: 520px;
  height: 100%;
}

.hero-photo-main {
  width: 100%;
  height: 100%;
  min-height: 520px;
  object-fit: cover;
  object-position: center top;
  display: block;
}

.hero-watermark-pattern {
  position: absolute;
  top: 0;
  right: 0;
  width: 220px;
  height: 220px;
  background-image: var(--iim-pattern);
  background-repeat: no-repeat;
  background-size: cover;
  opacity: 0.35;
  pointer-events: none;
}

.hero-badge-corner {
  position: absolute;
  bottom: 0;
  right: 0;
  background-color: #0c1720;
  padding: 24px 30px;
  color: #ffffff;
  z-index: 2;
}

