.books-page {
  background: #faf7f2;
  color: #39414a;
}

.books-page section[id] {
  scroll-margin-top: 92px;
}

.books-page .books-eyebrow {
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #800000;
  margin: 0 0 10px;
}

.books-page .books-h2 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(28px, 2.6vw, 38px);
  line-height: 1.22;
  color: #1c232b;
  font-weight: 700;
  letter-spacing: -0.02em;
  margin: 0 0 14px;
}

.books-page .books-lead,
.books-page .books-body {
  font-size: 15px;
  line-height: 1.7;
  color: #3b4756;
  margin: 0 0 22px;
}

.books-page .books-lead { max-width: 640px; }

.books-page .books-text-link {
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background-color: #800000 !important;
  border: 1px solid #800000 !important;
  color: #ffffff !important;
  padding: 10px 18px;
  border-radius: 4px;
  text-decoration: none !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  align-self: flex-start;
  margin-top: auto;
  box-shadow: 0 2px 6px rgba(128, 0, 0, 0.18);
  transition: all 0.25s ease;
}

.books-page .books-text-link i,
.books-page .books-text-link * {
  color: #ffffff !important;
  transition: transform 0.2s ease;
}

.books-page .books-text-link:hover {
  background-color: #660000 !important;
  border-color: #660000 !important;
  color: #ffffff !important;
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(128, 0, 0, 0.28);
}

.books-page .books-text-link:hover i {
  transform: translateX(3px);
  color: #ffffff !important;
}

.books-page .books-btn-maroon,
.books-page .books-btn-outline,
.books-page .books-btn-outline-light {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: 'DM Sans', sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 13px 18px;
  text-decoration: none;
  border-radius: 2px;
  line-height: 1;
}

.books-page .books-btn-maroon {
  background: #800000;
  color: #fff !important;
  border: 1px solid #800000;
}

.books-page .books-btn-maroon:hover { background: #800000; border-color: #800000; }

.books-page .books-btn-outline {
  background: transparent;
  color: #1c232b !important;
  border: 1px solid #6f675d;
}

.books-page .books-btn-outline:hover { background: #f4efe6; }

.books-page .books-btn-outline-light {
  background: transparent;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, 0.85);
}

.books-page .books-btn-outline-light:hover { background: rgba(255, 255, 255, 0.08); }

/* 01 HERO — same full-bleed treatment as the homepage */
.books-page .hero-books-seamless .hero-bg-img {
  width: 64%;
  height: 100%;
  top: 0;
  right: 0;
  object-fit: cover;
  object-position: center center;
}

/* 02 FEATURED */
.books-page .books-featured {
  background: #fff;
  padding: 64px 0 72px;
}

.books-page .books-featured-cover {
  display: block;
  width: 100%;
  max-width: 460px;
  height: auto;
  margin: 0 auto;
  object-fit: contain;
}

.books-page .books-featured-kicker {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 18px;
  line-height: 1.4;
  color: #3b4756;
  margin: 0 0 8px;
}

.books-page .books-featured-by {
  font-size: 14px;
  color: #5c6773;
  margin: 0 0 16px;
}

.books-page .books-featured .books-body {
  max-width: 520px;
}

.books-page .books-featured-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

/* 03 WORKS */
.books-page .books-works {
  background: #faf7f2;
  padding: 56px 0 64px;
}

.books-page .books-works-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 28px;
}

.books-page .books-works-head .books-h2 { margin-bottom: 0; }

.books-page .books-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 18px;
}

.books-page .books-work {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.books-page .books-work-cover {
  width: 100%;
  height: 268px;
  object-fit: contain;
  object-position: center bottom;
  display: block;
  margin-bottom: 12px;
}

.books-page .books-work h3 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 16px;
  line-height: 1.3;
  color: #1c232b;
  font-weight: 700;
  margin: 0 0 8px;
}

.books-page .books-work p {
  font-size: 13px;
  line-height: 1.55;
  color: #4a5560;
  margin: 0 0 12px;
