.books-page .books-modules {
  position: relative;
  background: #4c535a;
  padding: 58px 0 64px;
  color: #ebedee;
  overflow: hidden;
}

.books-page .books-modules::before {
  content: "";
  position: absolute;
  right: -30px;
  top: -40px;
  width: 280px;
  height: 280px;
  background-image: var(--iim-pattern);
  background-repeat: no-repeat;
  background-size: contain;
  opacity: 0.14;
  pointer-events: none;
}

.books-page .books-modules .container { position: relative; z-index: 1; }
.books-page .books-modules .books-eyebrow { color: #e2c48a; }
.books-page .books-modules .books-h2 { color: #fff; }
.books-page .books-modules .books-lead { color: #e0e3e6; max-width: 620px; }

.books-page .books-modules-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
  align-items: stretch;
}

.books-page .books-mod {
  background: #fff;
  min-height: 100%;
  overflow: hidden;
}

.books-page .books-mod-img {
  width: 100%;
  height: auto;
  object-fit: cover;
  object-position: center;
  display: block;
  background: transparent;
}

.books-page .books-mod-body { padding: 18px 22px 18px; }

.books-page .books-mod-split {
  display: flex;
  align-items: stretch;
  min-height: 248px;
}

.books-page .books-mod-split .books-mod-img {
  width: 220px;
  height: 248px;
  min-height: 248px;
  flex: 0 0 220px;
  object-fit: cover;
  object-position: center center;
}

.books-page .books-mod-split .books-mod-body {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 20px 22px 18px;
}

.books-page .books-mod-body h3 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 18px;
  line-height: 1.3;
  color: #1c232b;
  font-weight: 700;
  margin: 0 0 8px;
}

.books-page .books-mod-body p {
  font-size: 14px;
  line-height: 1.55;
  color: #4a5560;
  margin: 0 0 14px;
}

/* 05 REVIEWS */
.books-page .books-reviews {
  background: #fff;
  padding: 60px 0 64px;
}

.books-page .books-reviews-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}

.books-page .books-reviews-head .books-h2 {
  margin-bottom: 0;
}

.books-page .books-reviews-nav {
  display: flex;
  gap: 8px;
  flex-shrink: 0;
  margin-bottom: 4px;
}

.books-page .books-reviews-btn {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid #c4b8aa;
  background: #fff;
  color: #5a6570;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.books-page .books-reviews-viewport {
  overflow: hidden;
  container-type: inline-size;
  margin-top: 22px;
}

.books-page .books-reviews-track {
  display: flex;
  align-items: stretch;
  gap: 24px;
  width: max-content;
  transition: transform 0.5s ease;
}

.books-page .books-reviews-track.is-instant {
  transition: none;
}

.books-page .books-reviews-track .books-quote {
  flex: 0 0 calc((100cqi - 24px) / 2);
  width: calc((100cqi - 24px) / 2);
}

@media (max-width: 991px) {
  .books-page .books-reviews-track .books-quote {
    flex: 0 0 100cqi;
    width: 100cqi;
  }
}

@media (max-width: 767px) {
  .books-page .books-reviews-head {
    flex-direction: column;
    align-items: stretch;
  }

  .books-page .books-reviews-nav {
    align-self: flex-end;
    margin-top: 12px;
    margin-bottom: 0;
  }
}

.books-page .books-quote {
  background: #faf7f2;
  border: 0;
  margin: 0;
  padding: 28px 28px 24px;
  height: 100%;
}

.books-page .books-quote-mark {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 72px;
  line-height: 0.6;
  color: #c4a574;
  display: block;
  margin-bottom: 16px;
}

.books-page .books-quote p {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 16px;
  line-height: 1.6;
  color: #2a323a;
  margin: 0 0 20px;
}

.books-page .books-quote cite { display: block; font-style: normal; }

.books-page .books-quote cite strong {
  display: block;
  font-family: 'DM Sans', sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: #800000;
}

.books-page .books-quote cite span {
  display: block;
  font-family: 'DM Sans', sans-serif;
  font-size: 13px;
  color: #5a6570;
  margin-top: 2px;
}

/* 06 WHY */
.books-page .books-why {
  background: #faf7f2;
  padding: 56px 0 64px;
}

.books-page .books-why-head {
  text-align: center;
  margin-bottom: 36px;
}

.books-page .books-why-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 28px;
}

.books-page .books-why-item { text-align: center; }

.books-page .books-why-icon {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  border: 1.5px solid #800000;
  background: transparent;
  color: #800000;
  display: grid;
  place-items: center;
  margin: 0 auto 14px;
  font-size: 18px;
}

.books-page .books-why-item h3 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 18px;
  color: #1c232b;
  font-weight: 700;
  margin: 0 0 8px;
}

.books-page .books-why-item p {
  font-size: 13.5px;
  line-height: 1.55;
  color: #4a5560;
  margin: 0 auto;
