.books-page .books-cta {
  background: #4c535a;
  padding: 0;
  text-align: left;
  overflow: hidden;
}

.books-page .books-cta-media {
  position: relative;
  min-height: 0;
  background: #f3eee6;
}

.books-page .books-cta-img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center center;
  display: block;
}

.books-page .books-cta-panel {
  position: relative;
  display: flex;
  align-items: center;
  background: #4c535a;
  color: #fff;
  overflow: hidden;
}

.books-page .books-cta-panel::before {
  content: "";
  position: absolute;
  right: -20px;
  top: 50%;
  width: 240px;
  height: 240px;
  transform: translateY(-50%);
  background-image: var(--iim-pattern);
  background-repeat: no-repeat;
  background-size: contain;
  opacity: 0.16;
  pointer-events: none;
}

.books-page .books-cta-copy {
  position: relative;
  z-index: 1;
  padding: 20px 64px;
  max-width: 640px;
}

.books-page .books-cta-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(26px, 2.4vw, 34px);
  line-height: 1.25;
  color: #fff;
  font-weight: 700;
  margin: 0 0 14px;
}

.books-page .books-cta-lead {
  max-width: 480px;
  margin: 0 0 22px;
  color: #e0e3e6;
  font-size: 15px;
  line-height: 1.65;
}

.books-page .books-cta-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

@media (max-width: 1199px) {
  .books-page .books-grid { gap: 16px; }
  .books-page .books-work-cover { height: 190px; }
  .books-page .books-cta-copy { padding: 48px 40px; }
}

@media (max-width: 1024px) {
  .books-page .books-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .books-page .books-why-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 28px 20px; }
}

@media (max-width: 991px) {
  .books-page .hero-books-seamless .hero-bg-img {
    width: 100%;
    height: 100%;
    top: 0;
    right: 0;
    opacity: 0.25;
    object-fit: cover;
    object-position: center;
    transform: none;
  }
  .books-page .books-modules-grid {
    display: grid;
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .books-page .books-mod-split { display: block; }
  .books-page .books-mod-split .books-mod-img {
    width: 100%;
    flex: none;
    min-height: 0;
    height: 220px;
  }
  .books-page .books-cta-copy { padding: 28px 24px 32px; }
  .books-page .books-cta-media { min-height: 0; }
  .books-page .books-cta-img {
    position: relative;
    height: auto;
    aspect-ratio: 16 / 9;
  }
}

@media (max-width: 820px) {
  .books-page .books-grid { grid-template-columns: 1fr; }
  .books-page .books-works-head { flex-direction: column; align-items: flex-start; }
  .books-page .hero-books-seamless .hero-seamless-actions { flex-direction: column; align-items: flex-start; }
}

@media (max-width: 390px) {
  .books-page .books-grid { grid-template-columns: 1fr; }
  .books-page .books-why-grid { grid-template-columns: 1fr; }
  .books-page .books-work-cover { height: 260px; }
