.bio-page {
  background: #F9F7F3;
  color: #39414A;
}

.bio-page .bio-eyebrow {
  font-family: 'DM Sans', sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #800000;
  margin: 0 0 8px;
}

.bio-eyebrow-gold { color: #deb87b !important; }

.bio-page .bio-h2 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(24px, 2.6vw, 32px);
  line-height: 1.18;
  color: #20252B;
  font-weight: 700;
  margin: 0 0 12px;
}

.bio-h2-white { color: #fff !important; }

.bio-lead,
.bio-body,
.bio-aside {
  font-size: 13.5px;
  line-height: 1.6;
  color: #39414A;
  max-width: 720px;
  margin: 0 0 22px;
}

.bio-aside { max-width: none; margin: 0; font-size: 12.5px; }

.bio-sec { padding: 48px 0; background: #fff; }
.bio-sec-cream { background: #F9F7F3; }

.bio-btn-maroon,
.bio-btn-outline,
.bio-btn-outline-light,
.bio-btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: 'DM Sans', sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 11px 16px;
  text-decoration: none;
  border-radius: 1px;
  transition: 0.2s ease;
}

.bio-btn-maroon {
  background: #800000;
  color: #fff !important;
  border: 1px solid #800000;
}

.bio-btn-maroon:hover { background: #800000; }

.bio-btn-outline {
  background: #fff;
  color: #20252B !important;
  border: 1px solid #20252B;
}

.bio-btn-outline-light {
  background: transparent;
  color: #fff !important;
  border: 1px solid #fff;
}

.bio-btn-ghost {
  background: transparent;
  color: #fff !important;
  border: 1px solid #fff;
}

.bio-text-link {
  font-family: 'DM Sans', sans-serif;
  font-size: 10.5px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #800000 !important;
  text-decoration: none;
