.hero-bio-seamless .hero-bg-img {
  object-fit: cover;
  object-position: 72% center;
}

.hero-bio-seamless .hero-content-inner {
  max-width: 640px;
}

.hero-bio-seamless .hero-seamless-title {
  max-width: 640px;
}

.hero-bio-seamless .hero-seamless-title em {
  display: block;
}

.hero-bio-seamless .hero-seamless-lead,
.hero-bio-seamless .hero-seamless-actions,
.hero-bio-seamless .bio-hero-feats {
  max-width: 530px;
}

.hero-bio-seamless .bio-hero-feats {
  display: flex;
  flex-wrap: wrap;
  gap: 16px;
  margin-top: 26px;
}

.hero-bio-mark {
  position: absolute;
  top: 28px;
  right: 28px;
  z-index: 2;
  width: 108px;
  height: 108px;
  border-radius: 50%;
  background: rgba(74, 81, 88, 0.9);
  color: #deb87b;
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 13px;
  line-height: 1.25;
  display: grid;
  place-items: center;
  text-align: center;
  padding: 10px;
}

.hero-bio-quote {
  position: absolute;
  right: 0;
  bottom: 40px;
  z-index: 2;
  width: 248px;
  background: #4a5158;
  padding: 20px 22px;
}

.hero-bio-quote p {
  margin: 0;
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 16px;
  line-height: 1.4;
  color: #ffffff;
}

.bio-feat {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 11px;
  line-height: 1.3;
  color: #20252B;
  font-weight: 600;
  max-width: 160px;
}

.bio-feat-icon,
.bio-set-icon,
.bio-card-icon {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border: 1.5px solid #800000;
  border-radius: 50%;
  color: #800000;
  display: grid;
  place-items: center;
  font-size: 12px;
  background: #fff;
}

.bio-hero-visual { position: relative; height: 100%; min-height: 340px; }

.bio-page .bio-hero-img {
  width: 100%;
  height: 100%;
  min-height: 340px;
  object-fit: cover;
  display: block;
}

.bio-hero-mark {
  position: absolute;
  top: 16px;
  right: 16px;
  width: 88px;
  height: 88px;
  border-radius: 50%;
  background: rgba(74, 81, 88, 0.88);
  color: #deb87b;
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 11px;
  line-height: 1.2;
  display: grid;
  place-items: center;
  text-align: center;
  padding: 8px;
}

.bio-quote-card-hero {
  position: absolute;
  right: 0;
  bottom: 0;
  width: min(230px, 48%);
  background: #4a5158;
  color: #ebedee;
  padding: 16px 18px;
}

.bio-quote-card-hero p {
  margin: 0;
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: 13px;
  line-height: 1.45;
  color: #fff;
}

/* CARDS */
.bio-card {
  border: 1px solid #E8E4DF;
  background: #fff;
  height: 100%;
  position: relative;
}

.bio-card-img {
  width: 100%;
  height: 168px;
  object-fit: cover;
  display: block;
}

.bio-card-icon {
  position: absolute;
  top: 13px;
  left: 8px;
  right: 0;
  display: block;
  text-align: center;
  line-height: 34px;
}

.bio-card-body { padding: 28px 16px 18px; }

.bio-card-body h3,
.bio-set h3,
.bio-path-item h3,
.bio-res h3 {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 16px;
  color: #20252B;
  font-weight: 700;
  margin: 0 0 8px;
  line-height: 1.25;
}

.bio-card-body p,
.bio-set p,
.bio-path-item p,
.bio-res p {
  font-size: 12.5px;
  line-height: 1.55;
  color: #39414A;
  margin: 0;
}

.bio-set { padding: 8px 6px; }
.bio-set-icon { width: 46px; height: 46px; flex-basis: 46px; font-size: 16px; margin: 0 auto 10px; }

/* PATHWAY */
.bio-path {
  display: flex;
  align-items: stretch;
  gap: 8px;
}

.bio-path-item {
  flex: 1;
  border: 1px solid #E8E4DF;
  background: #fff;
  padding: 18px 14px 16px;
  text-align: center;
  position: relative;
}

.bio-path-num {
  position: absolute;
  top: -10px;
  left: 12px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: #800000;
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  display: grid;
  place-items: center;
}

.bio-path-arrow {
  display: flex;
  align-items: center;
  color: #800000;
  font-size: 12px;
  flex: 0 0 auto;
}

/* TOPICS */
.bio-topics {
  background: #4a5158;
  padding: 44px 0 40px;
}

.bio-topic-row {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 10px;
}

.bio-topic-card {
  background: #3a4148;
  overflow: hidden;
  position: relative;
}

.bio-topic-card img {
  width: 100%;
  height: 150px;
  object-fit: cover;
  display: block;
}

.bio-topic-num {
  position: absolute;
  top: 8px;
  left: 8px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #800000;
  color: #fff;
  font-size: 10px;
  font-weight: 800;
  display: grid;
  place-items: center;
}

.bio-topic-card h3 {
  background: #fff;
  margin: 0;
  padding: 10px 8px 12px;
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 12px;
  line-height: 1.3;
  color: #20252B;
  min-height: 62px;
}

/* RESOURCES */
.bio-res img {
  width: 100%;
  height: auto;
  aspect-ratio: 4 / 3;
  object-fit: cover;
  object-position: center center;
  display: block;
  margin-bottom: 10px;
  border: 1px solid #E8E4DF;
}

/* STUDENT GRID */
.bio-tall-photo {
  width: 100%;
  height: 380px;
  object-fit: cover;
  display: block;
}

.bio-stack-photo {
  width: 100%;
  height: 182px;
  object-fit: cover;
  display: block;
}

/* EDITORIAL */
.bio-ed { display: flex; gap: 16px; align-items: flex-start; }
.bio-ed-copy { flex: 1; }
.bio-ed-img {
  width: 42%;
  max-width: 220px;
  height: 180px;
  object-fit: cover;
  flex-shrink: 0;
}

/* QUOTE */
.conf-quote-section {
  background: #10243a;
  padding: 56px 0;
}
.conf-quote-inner {
  max-width: 720px;
  margin: 0 auto;
  text-align: center;
  position: relative;
}
.conf-quote-mark {
  font-family: Georgia, serif;
  font-size: 5rem;
  line-height: 0.5;
  color: rgba(226,196,138,0.3);
  display: block;
  margin-bottom: 16px;
}
.conf-quote-text {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-style: italic;
  color: #fff;
  line-height: 1.7;
  margin-bottom: 20px;
}
.conf-quote-attr {
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: #e2c48a;
}

/* CTA */
.bio-cta {
  background: #4a5158;
  background-image: var(--iim-pattern);
  background-repeat: no-repeat;
  background-position: right -40px center;
  background-size: 280px;
  padding: 52px 0;
  color: #fff;
}

.bio-cta-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(24px, 3vw, 36px);
  color: #fff;
  margin: 0 0 12px;
}

.bio-cta-lead {
  max-width: 560px;
  margin: 0 auto 20px;
  color: #d5d8db;
  font-size: 14px;
  line-height: 1.6;
}

.bio-cta-actions { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; }

/* TEAM */
.bio-team {
  display: flex;
  gap: 14px;
  justify-content: flex-end;
}

.bio-member { margin: 0; text-align: center; flex: 1; max-width: 110px; }

.bio-member img {
  width: 88px;
  height: 88px;
  border-radius: 50%;
  object-fit: cover;
  display: block;
  margin: 0 auto 8px;
}

.bio-member strong {
  display: block;
  font-size: 11px;
  color: #20252B;
  font-family: 'DM Sans', sans-serif;
}

.bio-member span {
  display: block;
  font-size: 10px;
  color: #5c6773;
}

@media (max-width: 1199px) {
  .bio-topic-row { grid-template-columns: repeat(4, 1fr); }
}

@media (max-width: 991px) {
  .hero-bio-mark { display: none; }
  .hero-bio-quote {
    position: static;
    width: 100%;
    margin-top: 20px;
  }
  .bio-tall-photo { min-height: 240px; height: 240px; }
  .bio-stack-photo { height: 180px; }
  .bio-path { flex-wrap: wrap; }
  .bio-path-item { flex: 1 1 42%; }
  .bio-path-arrow { display: none; }
  .bio-ed { flex-direction: column; }
  .bio-ed-img { width: 100%; max-width: none; }
  .bio-team { flex-wrap: wrap; justify-content: flex-start; }
  .bio-topic-row { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 575px) {
  .bio-topic-row { grid-template-columns: 1fr; }
  .bio-hero-feats { flex-direction: column; }
}

