.mission-page {
  background: #fff;
  color: #39444d;
  overflow-x: clip;
}

.msn-eyebrow {
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #800000;
  margin: 0 0 10px;
}

.msn-eyebrow--center {
  text-align: center;
}

.msn-bar {
  display: block;
  width: 36px;
  height: 2px;
  background: #800000;
  margin: 0 0 18px;
}

.msn-bar--center {
  margin: 0 auto 22px;
}

.msn-h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(26px, 2.5vw, 34px);
  line-height: 1.25;
  color: #172331;
  font-weight: 700;
  margin: 0 0 14px;
}

.msn-body {
  font-size: 14.5px;
  line-height: 1.7;
  color: #39444d;
  margin: 0;
  max-width: 46ch;
}

.msn-lead {
  font-size: 14.5px;
  line-height: 1.65;
  color: #5a6570;
  max-width: 720px;
  margin: 0;
}

.msn-lead--center {
  margin: 0 auto;
  text-align: center;
}

.msn-section-intro {
  margin-bottom: 28px;
}

.msn-section-intro--left .msn-lead {
  max-width: 640px;
}

.msn-text-link {
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #800000 !important;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin-top: auto;
}

.msn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 13px 18px;
  border-radius: 1px;
  line-height: 1;
  white-space: nowrap;
}

.msn-btn-fill {
  background: #800000;
  color: #fff !important;
  border: 1px solid #800000;
}

.msn-btn-fill:hover {
  background: #800000;
  border-color: #800000;
}

.msn-btn-light {
  background: transparent;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, 0.85);
}

.msn-btn-light:hover {
  background: rgba(255, 255, 255, 0.08);
}

.msn-icon-circle {
  width: 54px;
  height: 54px;
  border-radius: 50%;
  background: #800000;
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 18px;
  margin: 0 auto 14px;
}

.msn-icon-circle--burgundy {
  background: #800000;
}

.msn-icon-circle--green {
  background: #4a5158;
}

/* --------------------------------------------------------------------------
   01 HERO
   -------------------------------------------------------------------------- */

.mission-page .hero-mission-seamless {
  background-color: #faf8f4;
  border-bottom: 1px solid #e8e3dc;
  min-height: 540px;
}

.mission-page .hero-mission-seamless .hero-bg-img {
  object-position: 68% 40%;
  width: 66%;
}

.mission-page .hero-mission-seamless .hero-gradient-overlay {
  background: linear-gradient(
    90deg,
    #faf8f4 0%,
    #faf8f4 30%,
    rgba(250, 248, 244, 0.92) 40%,
    rgba(250, 248, 244, 0.4) 52%,
    rgba(250, 248, 244, 0) 64%
  );
}

.mission-page .hero-mission-seamless .hero-watermark-overlay {
  right: 36px;
  top: 18px;
  opacity: 0.22;
}

.mission-page .msn-hero-eyebrow {
  color: #800000;
  font-weight: 800;
}

.mission-page .hero-mission-seamless .hero-seamless-title {
  font-size: clamp(38px, 4.4vw, 56px);
  line-height: 1.12;
  color: #172331;
}

.mission-page .hero-mission-seamless .hero-seamless-title em {
  color: #800000;
  font-style: italic;
  font-weight: 400;
}

.mission-page .hero-mission-seamless .btn-seamless-maroon {
  background-color: #800000;
  border-color: #800000;
  gap: 8px;
}

.mission-page .hero-mission-seamless .btn-seamless-outline {
  background-color: #faf8f4;
  border-color: #800000;
  color: #800000 !important;
  gap: 8px;
}

.mission-page .msn-hero-quote {
  right: 28px;
  bottom: 36px;
  background: #4a5158;
  padding: 18px 22px 20px;
  max-width: 248px;
  position: absolute;
  z-index: 4;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.18);
}

.mission-page .msn-hero-quote::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--iim-pattern);
  background-size: 140px;
  opacity: 0.1;
  pointer-events: none;
}

.mission-page .msn-hero-quote .quote-text {
  position: relative;
  z-index: 1;
  font-size: 18px;
  line-height: 1.38;
  color: #fff !important;
  text-shadow: none;
}

/* --------------------------------------------------------------------------
   02 MISSION STATEMENT
   -------------------------------------------------------------------------- */

.msn-statement {
  background: #faf8f4;
  padding: 72px 0 76px;
  position: relative;
  border-bottom: 1px solid #ebe4da;
}

.msn-statement::before,
.msn-statement::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 160px;
  background-image: var(--iim-pattern);
  background-size: 180px;
  opacity: 0.06;
  pointer-events: none;
}

.msn-statement::before {
  left: 0;
}

.msn-statement::after {
  right: 0;
}

.msn-statement .container {
  max-width: 1100px;
}

.msn-statement-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width:100%;
  margin: 0 auto;
  text-align: center;
  padding: 0;
}

.msn-statement-text {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(20px, 2vw, 27px);
  line-height: 1.55;
  color: #172331;
  margin: 0;
  width: 100%;
}

.msn-statement-text em {
  color: #800000;
  font-style: italic;
  font-weight: 400;
}

/* --------------------------------------------------------------------------
   03 VISION
   -------------------------------------------------------------------------- */

.msn-vision {
  background: #fff;
}

.msn-vision-row {
  min-height: 420px;
}

.msn-vision-media {
  min-height: 420px;
  position: relative;
}

.msn-vision-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.msn-vision-copy {
  padding: 56px 48px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: #fff;
}

.msn-vision-quote {
  position: relative;
  background: #faf8f4;
  padding: 56px 40px;
  display: flex;
  align-items: center;
  overflow: hidden;
  border-left: 1px solid #ebe4da;
}

.msn-vision-quote::before {
  content: "";
  position: absolute;
  top: -40px;
  right: -60px;
  bottom: -40px;
  width: 280px;
  background-image: var(--iim-pattern);
  background-size: 240px;
  opacity: 0.14;
  pointer-events: none;
}

.msn-vision-quote p {
  position: relative;
  z-index: 1;
  font-family: "Libre Baskerville", Georgia, serif;
  font-style: italic;
  font-size: clamp(28px, 2.6vw, 38px);
  line-height: 1.32;
  color: #800000;
  margin: 0;
}

/* --------------------------------------------------------------------------
   04 VALUES
   -------------------------------------------------------------------------- */

.msn-values {
  background: #fff;
  padding: 56px 0 60px;
  border-top: 1px solid #ebe4da;
  border-bottom: 1px solid #ebe4da;
}

.msn-values-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.msn-value-card {
  background: #faf8f4;
  border: 1px solid #e8e3dc;
  padding: 26px 14px 22px;
  text-align: center;
}

.msn-value-card h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 16px;
  color: #800000;
  font-weight: 700;
  margin: 0 0 8px;
}

.msn-value-card p {
  font-size: 12.5px;
  line-height: 1.5;
  color: #5a6570;
  margin: 0;
}

/* --------------------------------------------------------------------------
   05 PILLARS
   -------------------------------------------------------------------------- */

.msn-pillars {
  background: #fff;
  padding: 56px 0 60px;
}

.msn-pillars-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.msn-pillar-card {
  background: #fff;
  border: 1px solid #e8e3dc;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.msn-pillar-media img {
  width: 100%;
  height: 168px;
  object-fit: cover;
  display: block;
}

.msn-pillar-body {
  padding: 16px 16px 18px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.msn-pillar-label {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.msn-pillar-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #fff;
  border: 1.5px solid #800000;
  color: #800000;
  display: grid;
  place-items: center;
  font-size: 13px;
}

.msn-pillar-body h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 16px;
  color: #800000;
  font-weight: 700;
  margin: 0;
  line-height: 1.25;
}

.msn-pillar-body p {
  font-size: 13px;
  line-height: 1.55;
  color: #5a6570;
  margin: 0 0 16px;
  flex: 1;
}

/* --------------------------------------------------------------------------
   06 WHO WE SERVE
   -------------------------------------------------------------------------- */

.msn-serve {
  background: #faf8f4;
  padding: 56px 0 60px;
  border-top: 1px solid #ebe4da;
  border-bottom: 1px solid #ebe4da;
}

.msn-serve-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 14px;
}

.msn-serve-card {
  background: #fff;
  border: 1px solid #e8e3dc;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.msn-serve-media img {
  width: 100%;
  height: 128px;
  object-fit: cover;
  display: block;
}

.msn-serve-body {
  padding: 14px 14px 16px;
}

.msn-serve-label {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 8px;
}

.msn-serve-icon {
  width: 30px;
  height: 30px;
  flex-shrink: 0;
  border-radius: 50%;
  background: #fff;
  border: 1.5px solid #800000;
  color: #800000;
  display: grid;
  place-items: center;
  font-size: 12px;
}

.msn-serve-body h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 14.5px;
  color: #800000;
  font-weight: 700;
  margin: 0;
  line-height: 1.25;
}

.msn-serve-body p {
  font-size: 12.5px;
  line-height: 1.5;
  color: #5a6570;
  margin: 0;
}

/* --------------------------------------------------------------------------
   07 JOURNEY
   -------------------------------------------------------------------------- */

.msn-journey {
  background: #faf8f4;
  padding: 56px 0 58px;
}

.msn-journey-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 28px;
  margin-bottom: 32px;
}

.msn-journey-aside {
  font-size: 14px;
  line-height: 1.6;
  color: #5a6570;
  max-width: 420px;
  margin: 0 0 4px;
}

.msn-journey-track {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.msn-journey-item {
  text-align: center;
  padding: 0 6px;
}

.msn-journey-node {
  position: relative;
  display: flex;
  justify-content: center;
  margin-bottom: 14px;
}

.msn-journey-node .msn-icon-circle {
  margin: 0;
}

.msn-journey-arrow {
  position: absolute;
  right: -8px;
  top: 50%;
  transform: translateY(-50%);
  color: #c4b8aa;
  font-size: 14px;
}

.msn-journey-item h3 {
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #800000;
  margin: 0 0 8px;
}

.msn-journey-item p {
  font-size: 12.5px;
  line-height: 1.5;
  color: #5a6570;
  margin: 0 auto;
  max-width: 220px;
}

/* --------------------------------------------------------------------------
   08 FINAL CTA
   -------------------------------------------------------------------------- */

.msn-cta {
  background: #4a5158;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
  border-bottom: 4px solid #c5c8cb;
}

.msn-cta-inner {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(200px, 0.28fr);
  min-height: 250px;
  align-items: stretch;
  background: #4a5158;
}

.msn-cta-inner::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--iim-pattern);
  background-size: 220px;
  background-repeat: repeat;
  opacity: 0.14;
  filter: sepia(1) saturate(2.2) hue-rotate(5deg) brightness(1.35);
  pointer-events: none;
  z-index: 0;
}

.msn-cta-body {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 28px 40px;
  padding: 40px 36px 40px 56px;
  color: #fff;
}

.msn-cta-copy {
  max-width: 520px;
  flex: 1 1 auto;
}

.msn-cta-eyebrow {
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #d4b06a;
  margin: 0 0 12px;
}

.msn-cta-copy h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(26px, 2.4vw, 36px);
  line-height: 1.28;
  color: #fff;
  font-weight: 700;
  margin: 0 0 12px;
}

.msn-cta-copy > p {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 15px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.92);
  max-width: 46ch;
  margin: 0;
}

.msn-cta-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: flex-end;
}

.msn-cta .msn-btn-fill {
  background: #800000;
  border: 1px solid rgba(255, 255, 255, 0.9);
  color: #fff !important;
}

.msn-cta .msn-btn-fill:hover {
  background: #800000;
  border-color: #fff;
}

.msn-cta .msn-btn-light {
  background: transparent;
  border: 1px solid rgba(255, 255, 255, 0.9);
  color: #fff !important;
}

.msn-cta .msn-btn-light:hover {
  background: rgba(255, 255, 255, 0.08);
}

.msn-cta-media {
  position: relative;
  z-index: 1;
  min-height: 250px;
  overflow: hidden;
}

.msn-cta-media::before {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: 72px;
  background: linear-gradient(90deg, #4a5158 0%, rgba(74, 81, 88, 0) 100%);
  z-index: 2;
  pointer-events: none;
}

.msn-cta-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

/* --------------------------------------------------------------------------
   RESPONSIVE
   -------------------------------------------------------------------------- */

@media (max-width: 1100px) {
  .msn-values-grid,
  .msn-serve-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .msn-pillars-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 991px) {
  .mission-page .hero-mission-seamless .hero-bg-img {
    width: 100%;
    opacity: 0.35;
    object-position: center 30%;
  }

  .mission-page .hero-mission-seamless .hero-gradient-overlay {
    background: linear-gradient(
      180deg,
      rgba(250, 248, 244, 0.94) 0%,
      rgba(250, 248, 244, 0.88) 100%
    );
  }

  .mission-page .msn-hero-quote {
    position: static;
    margin-top: 20px;
    max-width: none;
  }

  .mission-page .msn-hero-quote .quote-text {
    color: #fff !important;
  }

  .msn-vision-media {
    min-height: 280px;
  }

  .msn-vision-copy,
  .msn-vision-quote {
    padding: 36px 28px;
  }

  .msn-journey-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .msn-journey-track {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    row-gap: 24px;
  }

  .msn-journey-arrow {
    display: none;
  }

  .msn-cta-inner {
    grid-template-columns: 1fr;
  }

  .msn-cta-media {
    min-height: 220px;
    order: -1;
  }

  .msn-cta-media::before {
    width: 100%;
    height: 64px;
    inset: auto 0 0 0;
    background: linear-gradient(0deg, #4a5158 0%, rgba(74, 81, 88, 0) 100%);
  }

  .msn-cta-body {
    flex-direction: column;
    align-items: flex-start;
    padding: 36px 28px;
  }

  .msn-cta-actions {
    justify-content: flex-start;
  }
}

@media (max-width: 767px) {
  .msn-statement,
  .msn-values,
  .msn-pillars,
  .msn-serve,
  .msn-journey {
    padding: 44px 0 48px;
  }

  .msn-values-grid,
  .msn-pillars-grid,
  .msn-serve-grid,
  .msn-journey-track {
    grid-template-columns: 1fr;
  }

  .msn-statement::before,
  .msn-statement::after {
    width: 60px;
  }

  .msn-cta-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .mission-page .hero-seamless-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .mission-page .hero-seamless-actions a {
    justify-content: center;
  }
}


