.educate-page {
  background: #fff;
  color: #39444d;
  overflow-x: clip;
}

.educate-page section[id] {
  scroll-margin-top: 92px;
}

.edu-eyebrow {
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: #800000;
  margin: 0 0 10px;
}

.edu-h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(26px, 2.5vw, 34px);
  line-height: 1.22;
  color: #172331;
  font-weight: 700;
  margin: 0 0 12px;
}

.edu-body {
  font-size: 14.5px;
  line-height: 1.7;
  color: #39444d;
  margin: 0 0 22px;
  max-width: 42ch;
}

.edu-section-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 24px;
  margin-bottom: 28px;
}

.edu-section-aside {
  font-size: 13.5px;
  line-height: 1.55;
  color: #5a6570;
  max-width: 280px;
  text-align: right;
  margin: 0 0 4px;
  flex: 0 1 280px;
}

.edu-text-link {
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background-color: #800000 !important;
  border: 1px solid #800000 !important;
  color: #ffffff !important;
  padding: 10px 18px;
  border-radius: 4px;
  text-decoration: none !important;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  align-self: flex-start;
  margin-top: auto;
  box-shadow: 0 2px 6px rgba(128, 0, 0, 0.18);
  transition: all 0.25s ease;
}

.edu-text-link i,
.edu-text-link * {
  color: #ffffff !important;
  transition: transform 0.2s ease;
}

.edu-text-link:hover {
  background-color: #660000 !important;
  border-color: #660000 !important;
  color: #ffffff !important;
  transform: translateY(-2px);
  box-shadow: 0 6px 14px rgba(128, 0, 0, 0.28);
}

.edu-text-link:hover i {
  transform: translateX(3px);
  color: #ffffff !important;
}

.edu-view-all-wrap {
  margin-top: 32px;
  text-align: center;
}

.edu-view-all-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 28px;
  background: var(--maroon);
  color: #fff;
  font-family: 'DM Sans', sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.edu-view-all-link:hover {
  background: var(--ink);
  color: #fff;
}

.edu-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 13px 18px;
  border-radius: 1px;
  line-height: 1;
  white-space: nowrap;
}

.edu-btn i {
  font-size: 10px;
}

.edu-btn-fill {
  background: #800000;
  color: #fff !important;
  border: 1px solid #800000;
}

.edu-btn-fill:hover {
  background: #800000;
  border-color: #800000;
}

.edu-btn-light {
  background: transparent;
  color: #fff !important;
  border: 1px solid rgba(255, 255, 255, 0.85);
}

.edu-btn-light:hover {
  background: rgba(255, 255, 255, 0.08);
}

.edu-quote-mark {
  display: block;
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 64px;
  line-height: 0.7;
  color: #800000;
  margin-bottom: 10px;
}

.edu-quote-line {
  width: 48px;
  height: 2px;
  background: #800000;
}

