   -------------------------------------------------------------------------- */

.edu-mission {
  background: #fff;
  padding: 64px 0 70px;
}

.edu-mission-grid {
  display: grid;
  grid-template-columns: 1.05fr 1.15fr 0.85fr;
  gap: 28px;
  align-items: center;
}

.edu-mission-copy .edu-h2 {
  margin-bottom: 16px;
}

.edu-mission-media {
  min-width: 0;
}

.edu-mission-media img {
  width: 100%;
  height: 280px;
  object-fit: cover;
  display: block;
}

.edu-mission-quote {
  position: relative;
  background: #faf8f3;
  padding: 28px 22px 26px;
  min-height: 280px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
}

.edu-mission-quote::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--iim-pattern);
  background-size: 180px;
  background-repeat: repeat;
  opacity: 0.07;
  pointer-events: none;
}

.edu-mission-quote > * {
  position: relative;
  z-index: 1;
}

.edu-mission-quote p {
  font-family: "Libre Baskerville", Georgia, serif;
  font-style: italic;
