  line-height: 1.3;
  color: #800000;
  font-weight: 700;
  margin: 0 0 8px;
}

.edu-gain-item p {
  font-size: 12.5px;
  line-height: 1.5;
  color: #5a6570;
  margin: 0;
}

/* --------------------------------------------------------------------------
   08 TESTIMONIAL
   -------------------------------------------------------------------------- */

.edu-testimonial {
  background: #faf8f3;
}

.edu-testimonial-row {
  min-height: 360px;
}

.edu-testimonial-media {
  min-height: 360px;
  position: relative;
  background: #9f8c6e;
}

.edu-testimonial-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center center;
  display: block;
}

.edu-testimonial-copy {
  position: relative;
  padding: 56px 64px 56px 56px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  overflow: hidden;
  background: #faf8f3;
}

.edu-testimonial-copy::before {
  content: "";
  position: absolute;
  top: 0;
  right: 0;
  width: 220px;
  height: 220px;
  background-image: var(--iim-pattern);
  background-size: contain;
  background-repeat: no-repeat;
  opacity: 0.12;
  pointer-events: none;
}

.edu-testimonial-copy > * {
  position: relative;
  z-index: 1;
}

.edu-testimonial-copy p {
  font-family: "Libre Baskerville", Georgia, serif;
  font-style: italic;
  font-size: clamp(18px, 1.8vw, 24px);
  line-height: 1.55;
  color: #172331;
  max-width: 34ch;
  margin: 0 0 22px;
}

.edu-testimonial-attr {
  display: flex;
  align-items: center;
  gap: 14px;
}

.edu-testimonial-attr cite {
  font-family: "DM Sans", sans-serif;
  font-style: normal;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #800000;
}

/* --------------------------------------------------------------------------
   09 FINAL CTA
   -------------------------------------------------------------------------- */

.edu-cta {
  background: #4a5158;
  width: 100%;
  max-width: 100%;
}

.edu-cta-row {
  min-height: 420px;
  background: #4a5158;
  overflow: hidden;
}

.edu-cta-media {
  min-height: 420px;
  position: relative;
}

.edu-cta-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

.edu-cta-copy {
  position: relative;
  color: #fff;
  min-height: 420px;
  display: flex;
  align-items: center;
}

.edu-cta-copy::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--iim-pattern);
  background-size: 280px;
  background-repeat: repeat;
  opacity: 0.08;
  pointer-events: none;
}

.edu-cta-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  max-width: 720px;
  padding: 56px 48px 56px 56px;
}

.edu-cta-inner h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(28px, 2.6vw, 38px);
  line-height: 1.28;
  color: #fff;
  font-weight: 700;
  margin: 0 0 16px;
  max-width: 18ch;
}

.edu-cta-inner p {
  font-size: 15px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.88);
  max-width: 48ch;
  margin: 0 0 28px;
}

.edu-cta-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

/* --------------------------------------------------------------------------
   RESPONSIVE
   -------------------------------------------------------------------------- */

@media (max-width: 1199px) {
  .edu-path-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .edu-audience-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }

  .edu-mission-grid {
    grid-template-columns: 1fr 1fr;
  }

  .edu-mission-quote {
    grid-column: 1 / -1;
    min-height: auto;
  }
}

@media (max-width: 991px) {
  .educate-page .hero-educate-seamless .hero-bg-img {
    width: 100%;
    opacity: 0.28;
  }

  .educate-page .hero-educate-seamless .hero-gradient-overlay {
    background: linear-gradient(
      180deg,
      rgba(250, 248, 243, 0.96) 0%,
      rgba(250, 248, 243, 0.9) 100%
    );
  }

  .educate-page .edu-hero-stack {
    position: static;
    margin-top: 20px;
    text-align: left;
  }

  .educate-page .edu-hero-stack .quote-text {
    color: #172331;
    text-shadow: none;
    font-size: 12px;
  }

  .edu-section-head {
    flex-direction: column;
    align-items: flex-start;
  }

  .edu-section-aside {
    flex: none;
    text-align: left;
    max-width: 46ch;
  }

  .edu-mission-grid {
    grid-template-columns: 1fr;
  }

  .edu-mission-media img,
  .edu-mission-quote {
    height: auto;
    min-height: 0;
  }

  .edu-mission-media img {
    height: 240px;
  }

  .edu-path-grid,
  .edu-featured-grid,
  .edu-gains-grid,
  .edu-audience-grid {
    grid-template-columns: 1fr;
  }

  .edu-formats-track {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    row-gap: 28px;
  }

  .edu-formats-track::before {
    display: none;
  }

  .edu-gains-grid {
    gap: 22px;
  }

  .edu-gain-item:not(:last-child)::after {
    display: none;
  }

  .edu-testimonial-media,
  .edu-cta-media {
    min-height: 300px;
  }

  .edu-testimonial-copy {
    padding: 40px 28px;
  }

  .edu-cta-copy {
    min-height: auto;
  }

  .edu-cta-inner {
    padding: 40px 28px;
  }
}

@media (max-width: 767px) {
  .edu-mission,
  .edu-pathways,
  .edu-featured,
  .edu-formats,
  .edu-audience,
  .edu-gains {
    padding: 44px 0 48px;
  }

  .edu-path-grid,
  .edu-featured-grid,
  .edu-formats-track,
  .edu-gains-grid {
    grid-template-columns: 1fr;
  }

  .edu-audience-grid {
    grid-template-columns: 1fr;
  }

  .edu-cta-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .edu-cta-actions .edu-btn {
    width: 100%;
  }

  .educate-page .hero-educate-seamless .hero-content-inner {
    padding: 48px 0 40px;
  }

  .educate-page .hero-seamless-actions {
    flex-direction: column;
    align-items: stretch;
  }

  .educate-page .hero-seamless-actions a {
    justify-content: center;
  }
}

@media (max-width: 390px) {
  .edu-audience-grid {
    grid-template-columns: 1fr;
  }

  .edu-audience-item img {
    height: 200px;
  }
}


