.courses-page .hero-courses-seamless .hero-bg-img {
  object-position: center 32%;
}

.courses-page .hero-courses-seamless .hero-seamless-title {
  font-size: clamp(36px, 4vw, 56px);
  max-width: 520px;
}

/* 02 PARTNERS */
.crs-partners {
  background: #faf9f6;
  border-top: 1px solid #ebe4da;
  border-bottom: 1px solid #ebe4da;
  padding: 40px 0 38px;
}

.crs-partners .crs-section-head {
  margin-bottom: 26px;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 6px;
}

.crs-partners-marquee {
  overflow: hidden;
}

.crs-partners-track {
  display: flex;
  flex-wrap: nowrap;
  width: max-content;
  will-change: transform;
  animation: partner-logo-loop 28s linear infinite !important;
  animation-duration: 28s !important;
  animation-iteration-count: infinite !important;
}

.crs-partners-marquee:hover .crs-partners-track {
  animation-play-state: paused;
}

.crs-partner {
  position: relative;
  text-align: center;
  padding: 2px 14px 0;
  flex: 0 0 260px;
  width: 260px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.crs-partner:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  height: 88px;
  width: 1px;
  background: #e3dbd0;
}

.crs-partner-logo {
  width: 100%;
  max-width: 148px;
  height: 72px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin: 0 auto 12px;
}

.crs-partner-logo img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  object-position: center;
}

.crs-partner-edex .crs-partner-logo {
  max-width: 200px;
  height: 52px;
}

@keyframes partner-logo-loop {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}

.crs-partner-copy {
  width: 100%;
  max-width: 160px;
}

.crs-partner h3 {
  font-family: "DM Sans", sans-serif;
  font-size: 13.5px;
  font-weight: 700;
  color: #1a222c;
  margin: 0 0 5px;
  line-height: 1.25;
  letter-spacing: -0.01em;
}

.crs-partner-sub {
  display: block;
  font-family: "DM Sans", sans-serif;
  font-size: 9.5px;
  line-height: 1.3;
  color: #6b7280;
  margin: -1px auto 6px;
  max-width: 148px;
}

.crs-partner p {
  font-family: "DM Sans", sans-serif;
  font-size: 11.5px;
  line-height: 1.4;
  color: #6b7280;
  margin: 0 auto;
  max-width: 148px;
}

.crs-legacy-logo {
  width: 72px;
  height: 72px;
  flex: 0 0 72px;
  display: grid;
  place-items: center;
  overflow: hidden;
}

.crs-legacy-logo img {
  width: 64px;
  height: 64px;
  object-fit: contain;
  object-position: center;
}

.crs-legacy-wordmark {
  align-items: center;
}

.crs-legacy-wordmark .crs-legacy-logo {
  width: 128px;
  height: 56px;
  flex-basis: 128px;
}

.crs-legacy-wordmark .crs-legacy-logo img {
  width: 100%;
  height: 100%;
}

/* 03 PATHWAYS */
.crs-pathways {
  background: #faf8f4;
  padding: 48px 0 52px;
}

.crs-path-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 16px;
}

.crs-path {
  background: #fff;
  border: 1px solid #e7e1db;
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.crs-path-media {
  position: relative;
}

.crs-path-media img {
  width: 100%;
  aspect-ratio: 4 / 3;
  height: auto;
  object-fit: cover;
  object-position: center;
  display: block;
}

.crs-path-icon {
  position: absolute;
  left: 16px;
  bottom: -23px;
  top: auto;
  width: 46px;
  height: 46px;
  background: #fff;
  box-shadow: 0 1px 0 #e7e1db;
}

.crs-path-body {
  padding: 36px 16px 18px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.crs-path-body h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 18px;
  color: #17212c;
  margin: 0 0 8px;
  font-weight: 700;
}

.crs-path-body p {
  font-size: 13px;
  line-height: 1.5;
  color: #5a6570;
  margin: 0 0 16px;
  flex: 1;
}

.crs-path-arrow {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  background: #800000;
  color: #fff !important;
  display: grid;
  place-items: center;
  margin-left: auto;
  text-decoration: none;
  font-size: 12px;
}

/* 04 / 05 COURSES */
.crs-upcoming,
.crs-additional {
  background: #fff;
  padding: 48px 0 52px;
}

.crs-additional { background: #faf8f4; }

.crs-course-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px;
}

.crs-course {
  background: #fff;
  border: 1px solid #e7e1db;
  display: flex;
  flex-direction: column;
  min-height: 100%;
}

.crs-course-media {
  position: relative;
  height: 180px;
  overflow: hidden;
}

.crs-course-media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.crs-badge {
  position: absolute;
  left: 12px;
  top: 12px;
  background: #4a5158;
  color: #fff;
  font-family: "DM Sans", sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 10px;
  border-radius: 999px;
}

.crs-badge-soft {
  background: #f4e7b5;
  color: #5a4a18;
}

.crs-status-label {
  position: absolute;
  right: 12px;
  top: 12px;
  font-family: "DM Sans", sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 5px 10px;
  border-radius: 999px;
}

.crs-status-ongoing {
  background: #d1fae5;
  color: #065f46;
}

.crs-status-live {
  background: #800000;
  color: #fff;
}

.crs-course-body {
  padding: 18px 16px 16px;
  display: flex;
  flex-direction: column;
  flex: 1;
}

.crs-course-body h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 18px;
  line-height: 1.3;
  color: #4a5158;
  font-weight: 700;
  margin: 0 0 10px;
}

.crs-subtitle {
  font-family: "Libre Baskerville", Georgia, serif;
  font-style: italic;
  font-size: 14px;
  color: #5a6570;
  margin: -4px 0 12px;
}

.crs-course-body ul {
  list-style: none;
  padding: 0;
  margin: 0 0 14px;
}

.crs-course-body li {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  font-size: 12.5px;
  line-height: 1.45;
  color: #4a5560;
  margin-bottom: 6px;
}

.crs-course-body li i {
  color: #800000;
  width: 14px;
  margin-top: 2px;
  flex: 0 0 auto;
}

.crs-note {
  background: #fff8e6;
  border: 1px solid #efdfb0;
  color: #6a5a28;
  font-size: 12.5px;
  line-height: 1.45;
  padding: 10px 12px;
  margin: 0 0 14px;
}

.crs-course-foot {
  margin-top: auto;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
}

.crs-course-foot strong {
  font-family: "DM Sans", sans-serif;
  font-size: 22px;
  color: #800000;
  font-weight: 800;
}

/* 06 INSTITUTE */
.crs-institute {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr;
  min-height: 420px;
  background: #faf8f4;
}

.crs-institute-media { position: relative; min-height: 420px; }

.crs-institute-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 30%;
  display: block;
}

.crs-institute-copy {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 48px 48px 48px 56px;
}

.crs-institute-copy::before {
  content: "";
  position: absolute;
  right: -10px;
  top: 20px;
  width: 200px;
  height: 200px;
  background: var(--iim-pattern) no-repeat center / contain;
  opacity: 0.1;
  pointer-events: none;
}

.crs-inst-features {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
  margin: 8px 0 22px;
}

.crs-inst-features article { text-align: center; }

.crs-inst-features i {
  color: #800000;
  font-size: 22px;
  display: block;
  margin-bottom: 8px;
}

.crs-inst-features h3 {
  font-family: "DM Sans", sans-serif;
  font-size: 12.5px;
  font-weight: 700;
  line-height: 1.35;
  color: #17212c;
  margin: 0;
}

/* 07 HOW */
.crs-how {
  background: #fff;
  border-top: 1px solid #e7e1db;
  border-bottom: 1px solid #e7e1db;
  padding: 40px 0 36px;
  text-align: center;
}

.crs-how-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 18px;
  margin-top: 8px;
}

.crs-how-grid article { text-align: center; padding: 4px 10px; }

.crs-how-grid .crs-icon { margin: 0 auto 12px; }

.crs-how-grid h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 17px;
  color: #17212c;
  margin: 0 0 6px;
