.donate-page .hero-donate-seamless {
  min-height: 560px;
}

.donate-page .hero-donate-seamless .hero-container-relative {
  min-height: 560px;
}

.donate-page .hero-donate-seamless .hero-eyebrow-text-gold {
  color: var(--dn-burgundy);
}

.donate-page .hero-donate-seamless .hero-seamless-title {
  font-size: clamp(36px, 4.2vw, 54px);
  line-height: 1.12;
  max-width: 480px;
}

.donate-page .hero-donate-seamless .hero-seamless-lead {
  max-width: 470px;
  font-size: 14.5px;
}

.donate-page .hero-donate-seamless .hero-bg-img {
  width: 58%;
  object-position: 55% center;
}

.donate-page .donate-hero-actions {
  align-items: center;
}

.donate-page .donate-programs-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 16px 0 4px;
}

.donate-page .donate-program-link {
  display: inline-flex;
  align-items: center;
  padding: 5px 14px;
  border: 1.5px solid rgba(255,255,255,0.45);
  border-radius: 20px;
  color: #fff;
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  text-decoration: none;
  transition: background 0.18s, border-color 0.18s;
}

.donate-page .donate-program-link:hover {
  background: rgba(255,255,255,0.15);
  border-color: #fff;
  color: #fff;
  text-decoration: none;
}

.donate-page .donate-video-link {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  border: 0;
  background: transparent;
  color: var(--dn-burgundy);
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 0;
  cursor: pointer;
}

.donate-page .donate-video-link-icon {
  width: 34px;
  height: 34px;
  border: 1.5px solid var(--dn-burgundy);
  border-radius: 50%;
  display: inline-grid;
  place-items: center;
  font-size: 11px;
}

.donate-page .donate-hero-media-ui {
  position: absolute;
  inset: 0 0 0 42%;
  z-index: 2;
  pointer-events: none;
}

.donate-page .donate-hero-play {
  pointer-events: auto;
  position: absolute;
  left: 62%;
  top: 42%;
  transform: translate(-50%, -50%);
  width: 78px;
  height: 78px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.95);
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  font-size: 22px;
  display: grid;
  place-items: center;
  padding-left: 4px;
  cursor: pointer;
  transition: transform 0.25s ease, background 0.25s ease;
}

.donate-page .donate-hero-play:hover {
  transform: translate(-50%, -50%) scale(1.06);
  background: rgba(255, 255, 255, 0.2);
}

.donate-page .donate-hero-caption {
  pointer-events: none;
  position: absolute;
  right: 24px;
  bottom: 24px;
  max-width: 300px;
  color: #fff;
  background: rgba(10, 28, 36, 0.72);
  padding: 14px 16px;
}

.donate-page .donate-hero-caption strong {
  display: block;
  font-family: "DM Sans", sans-serif;
  font-size: 14px;
  font-weight: 700;
  margin-bottom: 4px;
}

.donate-page .donate-hero-caption span {
  font-size: 12px;
  line-height: 1.4;
  opacity: 0.92;
}

.donate-page .donate-video-modal {
  position: fixed;
  inset: 0;
  z-index: 2000;
  display: grid;
  place-items: center;
  padding: 24px;
}

.donate-page .donate-video-modal-backdrop {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(10, 18, 24, 0.78);
  cursor: pointer;
}

.donate-page .donate-video-modal-panel {
  position: relative;
  z-index: 1;
  width: min(920px, 100%);
  background: #0b1218;
  box-shadow: 0 24px 60px rgba(0, 0, 0, 0.45);
}

.donate-page .donate-video-modal-close {
  position: absolute;
  top: -42px;
  right: 0;
  width: 36px;
  height: 36px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  background: transparent;
  color: #fff;
  cursor: pointer;
  display: grid;
  place-items: center;
}

.donate-page .donate-video-modal-frame {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 9;
  background: #000;
}

.donate-page .donate-video-modal-frame iframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: 0;
}

.donate-page .donate-video-modal-fallback {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  margin: 10px 14px 12px;
  color: #f3efe7 !important;
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  text-decoration: none;
}

/* JOURNEY */
.donate-page .donate-journey {
  background: #fff;
  padding: 56px 0 48px;
  border-bottom: 1px solid var(--dn-line);
}

.donate-page .donate-journey-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 10px;
  margin-top: 28px;
}

.donate-page .donate-journey-top {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 14px;
}

.donate-page .donate-journey-icon {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--dn-burgundy);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 18px;
  flex: 0 0 52px;
}

.donate-page .donate-journey-icon.is-green {
  background: var(--dn-green);
}

.donate-page .donate-journey-arrow {
  color: #b7b1a8;
  font-size: 12px;
}

.donate-page .donate-journey-step h3 {
  font-family: "DM Sans", sans-serif;
  font-size: 14px;
  font-weight: 700;
  color: var(--dn-ink);
  margin: 0 0 8px;
  line-height: 1.3;
}

.donate-page .donate-journey-step p {
  font-size: 12.5px;
  line-height: 1.5;
  margin: 0;
  max-width: 180px;
}

/* VOICES + PANEL */
.donate-page .donate-voices-wrap {
  background: var(--dn-cream);
  padding: 56px 0 60px;
}

.donate-page .donate-voices-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(360px, 0.95fr);
  gap: 28px;
  align-items: start;
}

.donate-page .donate-filters {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-bottom: 22px;
}

.donate-page .donate-filter {
  border: 1px solid #d9d2c8;
  background: #fff;
  color: var(--dn-ink);
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  font-weight: 600;
  padding: 8px 14px;
  border-radius: 999px;
  cursor: pointer;
}

.donate-page .donate-filter.is-active {
  background: var(--dn-burgundy);
  border-color: var(--dn-burgundy);
  color: #fff;
}

.donate-page .donate-voice-cards {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}

.donate-page .donate-voice-card {
  background: #fff;
  border: 1px solid var(--dn-line);
  padding: 0 0 14px;
}

.donate-page .donate-voice-thumb {
  position: relative;
  display: block;
  width: 100%;
  border: 0;
  padding: 0;
  cursor: pointer;
  background: #ddd;
  aspect-ratio: 4 / 3;
  overflow: hidden;
}

.donate-page .donate-voice-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.donate-page .donate-voice-play {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  color: var(--dn-burgundy);
  display: grid;
  place-items: center;
  font-size: 13px;
  padding-left: 2px;
}

.donate-page .donate-voice-time {
  position: absolute;
  right: 8px;
  bottom: 8px;
  background: rgba(0, 0, 0, 0.65);
  color: #fff;
  font-size: 11px;
  padding: 2px 6px;
  border-radius: 2px;
}

.donate-page .donate-voice-quote {
  font-family: "Libre Baskerville", Georgia, serif;
  font-style: italic;
  font-size: 13.5px;
  line-height: 1.45;
  color: var(--dn-ink);
  margin: 12px 14px 10px;
  min-height: 78px;
}

.donate-page .donate-voice-meta {
  margin: 0 14px;
  padding-left: 10px;
  border-left: 2px solid var(--dn-burgundy);
}

.donate-page .donate-voice-meta strong {
  display: block;
  color: var(--dn-burgundy);
  font-family: "DM Sans", sans-serif;
  font-size: 13px;
  margin-bottom: 2px;
}

.donate-page .donate-voice-meta span {
  font-size: 12px;
  line-height: 1.35;
}

.donate-page .donate-voice-nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  margin-top: 18px;
}

.donate-page .donate-voice-controls {
  display: flex;
  align-items: center;
  gap: 10px;
}

.donate-page .donate-voice-controls > button {
  width: 34px;
  height: 34px;
  border: 1px solid #d5cec4;
  background: #fff;
  color: var(--dn-ink);
  display: grid;
  place-items: center;
  cursor: pointer;
}

.donate-page .donate-voice-controls > button:disabled {
  opacity: 0.35;
  cursor: not-allowed;
}

.donate-page .donate-dots {
  display: flex;
  gap: 6px;
  margin-left: 6px;
}

.donate-page .donate-dots button {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  border: 0;
  background: #cfc7bb;
  padding: 0;
  cursor: pointer;
}

.donate-page .donate-dots button.is-active {
  background: var(--dn-burgundy);
}

/* Donation panel */
.donate-page .donate-panel {
  background: #fffdf8;
  border: 1px solid #e4ddd3;
  padding: 26px 22px 22px;
  border-radius: 4px;
}

.donate-page .donate-panel-lead {
  font-size: 13.5px;
  line-height: 1.55;
  margin: 0 0 18px;
}

.donate-page .donate-freq {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0;
  margin-bottom: 16px;
  border: 1px solid #ddd5ca;
  border-radius: 999px;
  overflow: hidden;
  background: #fff;
}

.donate-page .donate-freq button {
  border: 0;
  background: transparent;
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  font-weight: 700;
  padding: 10px 12px;
  cursor: pointer;
  color: var(--dn-ink);
}

.donate-page .donate-freq button.is-active {
  background: var(--dn-burgundy);
  color: #fff;
}

.donate-page .donate-amounts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-bottom: 14px;
}

.donate-page .donate-amount {
  border: 1px solid #ddd5ca;
  background: #fff;
  text-align: left;
  padding: 12px 10px;
  min-height: 78px;
  cursor: pointer;
  border-radius: 2px;
}

.donate-page .donate-amount strong {
  display: block;
  font-family: "DM Sans", sans-serif;
  font-size: 18px;
  color: var(--dn-ink);
  margin-bottom: 4px;
}

.donate-page .donate-amount span {
  display: block;
  font-size: 11px;
  line-height: 1.3;
  color: #6b7280;
}

.donate-page .donate-amount.is-selected {
  border-color: var(--dn-burgundy);
  border-width: 2px;
  padding: 11px 9px;
  box-shadow: inset 0 0 0 1px var(--dn-burgundy);
}

.donate-page .donate-custom {
  display: grid;
  gap: 6px;
  margin-bottom: 12px;
  font-size: 12px;
  font-weight: 600;
}

.donate-page .donate-custom input {
  border: 1px solid #ddd5ca;
  padding: 10px 12px;
  font-size: 14px;
}

.donate-page .donate-submit {
  width: 100%;
  border: 0;
  background: var(--dn-burgundy-deep);
  color: #fff;
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  padding: 14px 16px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  cursor: pointer;
  margin-bottom: 14px;
}

.donate-page .donate-submit:hover {
  background: #800000;
}

.donate-page .donate-checkout-note {
  font-size: 11.5px;
  line-height: 1.4;
  color: #6b7280;
  margin: -6px 0 12px;
}

.donate-page .donate-secure {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  text-align: left;
  padding-top: 4px;
}

.donate-page .donate-secure i {
  color: var(--dn-green);
  margin-top: 3px;
}

.donate-page .donate-secure strong {
  display: block;
  font-family: "DM Sans", sans-serif;
  font-size: 13px;
  color: var(--dn-ink);
  margin-bottom: 4px;
}

.donate-page .donate-secure p {
  font-size: 12px;
  line-height: 1.45;
  margin: 0;
}

/* IMPACT CARDS */
.donate-page .donate-impact {
  background: #fff;
  padding: 58px 0 54px;
}

.donate-page .donate-impact-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 28px;
}

.donate-page .donate-impact-cta {
  flex: 0 0 auto;
  white-space: nowrap;
}

.donate-page .donate-impact-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 14px;
}

.donate-page .donate-impact-card {
  position: relative;
  border-top: 1px solid var(--dn-line);
  padding-bottom: 4px;
}

.donate-page .donate-impact-card img {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  display: block;
}

.donate-page .donate-impact-icon {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: var(--dn-burgundy);
  color: #fff;
  display: grid;
  place-items: center;
  font-size: 14px;
  margin: -18px 0 12px 10px;
  position: relative;
  z-index: 1;
  border: 2px solid #fff;
}

.donate-page .donate-impact-card h3 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: 15px;
  line-height: 1.3;
  color: var(--dn-ink);
  margin: 0 0 8px;
  padding: 0 4px;
}

.donate-page .donate-impact-card p {
  font-size: 12.5px;
  line-height: 1.45;
  margin: 0;
  padding: 0 4px;
}

