.donate-page .donate-cta-band {
  background: #3e454c;
  width: 100%;
  max-width: 100%;
  overflow: hidden;
}

.donate-page .donate-cta-split {
  background: #3e454c;
  overflow: hidden;
  min-height: 440px;
  margin: 0;
}

.donate-page .donate-cta-copy {
  position: relative;
  color: #fff;
  min-height: 440px;
  display: flex;
  align-items: center;
  background: #3e454c;
  overflow: hidden;
}

.donate-page .donate-cta-copy::before {
  content: "";
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 120px;
  background-image: var(--iim-pattern);
  background-repeat: repeat-y;
  background-position: left center;
  background-size: 120px auto;
  opacity: 0.28;
  filter: sepia(1) saturate(3) hue-rotate(5deg) brightness(1.35);
  pointer-events: none;
  z-index: 0;
}

.donate-page .donate-cta-copy-inner {
  position: relative;
  z-index: 1;
  width: 100%;
  padding: 56px 40px 56px 56px;
  box-sizing: border-box;
}

.donate-page .donate-cta-copy h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(30px, 2.6vw, 40px);
  line-height: 1.25;
  margin: 0 0 18px;
  color: #fff;
  font-weight: 700;
  max-width: 34ch;
}

.donate-page .donate-cta-copy p {
  max-width: 52ch;
  font-size: 15px;
  line-height: 1.65;
  color: rgba(255, 255, 255, 0.92);
  margin: 0 0 26px;
}

.donate-page .donate-cta-btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  background: #800000;
  border: 1px solid #800000;
  color: #fff !important;
  font-family: "DM Sans", sans-serif;
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  text-decoration: none;
  padding: 14px 22px;
  border-radius: 3px;
  transition: background 0.2s ease, transform 0.2s ease;
}

.donate-page .donate-cta-btn:hover {
  background: #800000;
  border-color: #800000;
  transform: translateY(-1px);
}

.donate-page .donate-cta-media {
  min-height: 440px;
  position: relative;
}

.donate-page .donate-cta-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 45%;
  display: block;
}

/* PARTNERS */
.donate-page .donate-partners {
  background: var(--dn-cream);
  padding: 56px 0 64px;
  border-top: 1px solid var(--dn-line);
}

.donate-page .donate-partners-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 24px;
  margin-bottom: 28px;
}

.donate-page .donate-partners-marquee {
  overflow: hidden;
  width: 100%;
}

.donate-page .donate-partners-track {
  display: flex;
  flex-wrap: nowrap;
  width: max-content;
  will-change: transform;
  animation: partner-logo-loop 28s linear infinite;
}

.donate-page .donate-partners-marquee:hover .donate-partners-track {
  animation-play-state: paused;
}

.donate-page .donate-partner {
  position: relative;
  text-align: center;
  padding: 4px 12px 0;
  flex: 0 0 260px;
  width: 260px;
}

.donate-page .donate-partner:not(:last-child)::after {
  content: "";
  position: absolute;
  right: 0;
  top: 50%;
  transform: translateY(-50%);
  height: 88px;
  width: 1px;
  background: #e3dbd0;
}

.donate-page .donate-partner-logo {
  width: 100%;
  max-width: 148px;
  height: 72px;
  margin: 0 auto 12px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.donate-page .donate-partner-logo img {
  width: 100%;
  height: 100%;
  object-fit: contain;
}

.donate-page .donate-partner-edex .donate-partner-logo {
  width: 100%;
  max-width: 200px;
  height: 52px;
}

.donate-page .donate-partner-edex .donate-partner-logo img {
  width: 100%;
  height: 100%;
}

.donate-page .donate-partner h3 {
  font-family: "DM Sans", sans-serif;
  font-size: 13.5px;
  font-weight: 700;
  color: var(--dn-ink);
  margin: 0 0 6px;
}

.donate-page .donate-partner p {
  font-size: 11.5px;
  line-height: 1.4;
  margin: 0 auto;
  max-width: 148px;
  color: #6b7280;
}

/* Ensure partner-logo-loop keyframe is scoped near donate styles */
@keyframes partner-logo-loop {
  from { transform: translateX(0); }
  to   { transform: translateX(-50%); }
}

