.rs-cta {
  background: var(--rs-green);
  overflow: hidden;
}

.rs-cta-media {
  min-height: 420px;
  position: relative;
  overflow: hidden;
}

.rs-cta-media img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.rs-cta-copy {
  position: relative;
  color: #fff;
  min-height: 420px;
  display: flex;
  align-items: center;
  background: var(--rs-green);
}

.rs-cta-copy::before {
  content: "";
  position: absolute;
  inset: 0;
  background-image: var(--iim-pattern);
  background-size: 320px;
  background-repeat: repeat;
  opacity: 0.1;
  pointer-events: none;
}

.rs-cta-inner {
  position: relative;
  z-index: 1;
  padding: 48px 48px 48px 52px;
  max-width: 560px;
}

.rs-cta-inner .rs-eyebrow {
  color: rgba(255, 255, 255, 0.88);
  margin-bottom: 12px;
}

.rs-cta-inner h2 {
  font-family: "Libre Baskerville", Georgia, serif;
  font-size: clamp(26px, 2.6vw, 36px);
  line-height: 1.28;
  color: #fff;
  margin: 0 0 16px;
  font-weight: 700;
}

.rs-cta-inner > p {
  font-size: 15px;
  line-height: 1.7;
  color: rgba(255, 255, 255, 0.9);
  margin: 0 0 26px;
  max-width: 46ch;
}

.rs-cta-actions {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 12px;
}

.rs-cta-actions .rs-btn-light {
  background: #fff;
  border: 1px solid #fff;
  color: var(--rs-burgundy) !important;
}

.rs-cta-actions .rs-btn-light:hover {
  background: #f7eef1;
  border-color: #f7eef1;
  color: #800000 !important;
}

/* Research page responsive */
@media (max-width: 1199px) {
  .rs-approach-media img {
    height: 360px;
  }

  .rs-findings-copy {
    padding: 36px 28px;
  }

  .rs-edu-inner,
  .rs-cta-inner {
    padding: 40px 28px;
  }
}

