/* ── Dissemination Products Slider ── */
.mds-root { position: relative; }

.mds-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 20px;
}
.mds-counter { font-size: 13px; letter-spacing: 0.08em; color: #9a8778; }
.mds-counter-cur { font-size: 22px; font-weight: 700; color: #10243a; letter-spacing: 0; }
.mds-counter-sep { margin: 0 2px; }
.mds-header-nav { display: flex; gap: 8px; }

.mds-arrow {
  width: 40px; height: 40px;
  border-radius: 50%;
  border: 1.5px solid #d9cfc4;
  background: #fff;
  color: #10243a;
  display: flex; align-items: center; justify-content: center;
  cursor: pointer;
  transition: background 0.2s, border-color 0.2s, color 0.2s;
}
.mds-arrow:hover {
  background: #800000;
  border-color: #800000;
  color: #fff;
}

.mds-viewport { overflow: hidden; border-radius: 10px; }
.mds-track { display: flex; gap: 24px; will-change: transform; }

.mds-card {
  flex: 0 0 calc((100% - 24px) / 2);
  display: block;
  text-decoration: none;
  border-radius: 10px;
  overflow: hidden;
  position: relative;
  box-shadow: 0 2px 12px rgba(16,36,58,0.07);
  transition: box-shadow 0.3s, transform 0.3s;
}
.mds-card:hover {
  box-shadow: 0 10px 32px rgba(128,0,0,0.14);
  transform: translateY(-4px);
}

.mds-img-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 3 / 4;
  overflow: hidden;
  background: #1a1010;
}
.mds-img {
  width: 100%; height: 100%;
  object-fit: cover; display: block;
  transition: transform 0.5s cubic-bezier(0.4,0,0.2,1), opacity 0.3s;
}
.mds-card:hover .mds-img { transform: scale(1.06); opacity: 0.85; }

.mds-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to bottom, transparent 35%, rgba(10,8,8,0.72) 100%);
  pointer-events: none;
}

.mds-type-badge {
  position: absolute;
  top: 14px; left: 14px;
  background: rgba(128,0,0,0.88);
  color: #fff;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 4px 10px;
  border-radius: 20px;
  backdrop-filter: blur(4px);
}

.mds-card-footer {
  position: absolute;
  bottom: 0; left: 0; right: 0;
  padding: 20px 18px 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.mds-card-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 13px;
  font-weight: 700;
  color: #fff;
  margin: 0;
  line-height: 1.45;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  text-shadow: 0 1px 4px rgba(0,0,0,0.5);
}
.mds-view-btn {
  display: inline-flex;
  align-items: center;
  background: #fff;
  color: #800000;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 6px 14px;
  border-radius: 20px;
  width: fit-content;
  opacity: 0;
  transform: translateY(6px);
  transition: opacity 0.25s, transform 0.25s;
}
.mds-card:hover .mds-view-btn { opacity: 1; transform: translateY(0); }

.mds-dots {
  display: flex;
  justify-content: center;
  gap: 6px;
  margin-top: 22px;
}
.mds-dot {
  width: 24px; height: 4px;
  border-radius: 2px;
  background: #e0d5c8;
  border: none;
  cursor: pointer;
  transition: background 0.25s, width 0.25s;
}
.mds-dot--active {
  background: #800000;
  width: 40px;
}

@media (max-width: 640px) {
  .mds-card { flex: 0 0 100%; }
  .mds-view-btn { opacity: 1; transform: translateY(0); }
  .mds-counter-cur { font-size: 18px; }
  .mds-arrow { width: 34px; height: 34px; }
  .mds-card-title { font-size: 12px; }
}

