}

.bmd-btnSecondaryOutline {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: transparent;
  color: #800000;
  border: 1px solid #800000;
  border-radius: 4px;
  padding: 13px 24px;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
}

.bmd-btnSecondaryOutline:hover {
