  border-color: #630000;
}

.bmd-heroSubNote {
  font-size: 13px;
  font-style: italic;
  color: #727e8a;
  margin: 0;
}

.bmd-muslimedexLink {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
  font-size: 13px;
  font-weight: 600;
  color: var(--maroon);
}

.bmd-muslimedexLink:hover {
  color: var(--ink);
}

/* Hero Right Photographic Framing */
.bmd-heroMediaCol {
  flex: 1 1 46%;
  display: flex;
  justify-content: center;
  align-items: center;
  position: relative;
  z-index: 2;
}

.bmd-heroImageFrame {
  position: relative;
  width: 100%;
  max-width: 480px;
  aspect-ratio: 4 / 4.9;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 16px 40px rgba(16, 36, 58, 0.12), 0 2px 10px rgba(16, 36, 58, 0.06);
  border: 1px solid rgba(229, 222, 210, 0.8);
  background-color: #f5efe6;
}

.bmd-heroStillImg {
  object-fit: cover;
  object-position: center 25%;
