}

.bmd-heroImageFrame:hover .bmd-heroStillImg {
  transform: scale(1.02);
}

/* Quranic Quote Card Overlay */
.bmd-heroQuoteOverlay {
  position: absolute;
  bottom: 16px;
  right: 16px;
  left: 16px;
  background: rgba(255, 255, 255, 0.94);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  border: 1px solid rgba(233, 226, 216, 0.9);
  border-left: 3px solid #800000;
  border-radius: 8px;
  padding: 12px 16px;
  box-shadow: 0 8px 24px rgba(16, 36, 58, 0.1);
  pointer-events: none;
}

.bmd-heroQuoteText {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 13px;
  font-style: italic;
  line-height: 1.45;
  color: #10243a;
  margin-bottom: 4px;
}

.bmd-heroQuoteSource {
  display: block;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #800000;
  text-align: right;
}

/* --------------------------------------------------------------------------
   2. STICKY COURSE NAVIGATION
   -------------------------------------------------------------------------- */
.bmd-stickyNav {
  position: sticky;
  top: 0;
  z-index: 95;
  background-color: #ffffff;
  border-bottom: 1px solid #eae3d6;
  box-shadow: 0 2px 12px rgba(16, 36, 58, 0.04);
}

.bmd-navList {
  display: flex;
  align-items: center;
  justify-content: flex-start;
  list-style: none;
  margin: 0;
  padding: 0;
  gap: 32px;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}

.bmd-navList::-webkit-scrollbar {
  display: none;
}

.bmd-navItem {
  flex-shrink: 0;
}

.bmd-navLink {
  display: inline-flex;
  align-items: center;
  padding: 18px 2px 16px 2px;
  font-size: 14px;
  font-weight: 600;
  color: #556473;
  text-decoration: none;
  position: relative;
  transition: color 0.2s ease;
}

.bmd-navLink:hover {
  color: #800000;
}

.bmd-navLinkActive {
  color: #800000;
}

.bmd-activeIndicator {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 2.5px;
  background-color: #800000;
  border-radius: 2px 2px 0 0;
}

/* --------------------------------------------------------------------------
   3. ABOUT THIS COURSE SECTION
   -------------------------------------------------------------------------- */
.bmd-aboutSection {
  padding: 80px 0;
  background-color: #ffffff;
}

.bmd-aboutGrid {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 56px;
  align-items: start;
}

.bmd-aboutLeadCol {
  display: flex;
  flex-direction: column;
}

.bmd-aboutText {
  font-size: 16px;
  line-height: 1.75;
  color: #4e555c;
  margin-bottom: 20px;
}

.bmd-objectivesHeading {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 1.25rem;
  color: #800000;
  margin-top: 14px;
  margin-bottom: 18px;
  font-weight: 700;
}

.bmd-objectivesList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
}

.bmd-objectiveItem {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 15px;
  line-height: 1.55;
  color: #293845;
}

.bmd-checkCircle {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background-color: #800000;
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  flex-shrink: 0;
  margin-top: 2px;
}

/* Right Stacked Feature Cards */
