}

.bmd-featureCardIconWrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background-color: #ffffff;
  border: 1px solid #e5ded2;
  color: #800000;
  font-size: 18px;
  flex-shrink: 0;
  box-shadow: 0 2px 6px rgba(16, 36, 58, 0.04);
}

.bmd-featureCardLogoWrap {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 48px;
  border-radius: 8px;
  background-color: #ffffff;
  border: 1px solid #e5ded2;
