}

.bmd-featureCardContent {
  flex: 1;
}

.bmd-featureCardTitle {
  font-size: 15.5px;
  font-weight: 700;
  color: #10243a;
  margin-bottom: 4px;
}

.bmd-featureCardText {
  font-size: 13.5px;
  line-height: 1.5;
  color: #556473;
  margin: 0;
}

/* --------------------------------------------------------------------------
   4. COURSE CURRICULUM SECTION
   -------------------------------------------------------------------------- */
.bmd-curriculumSection {
  background-color: #faf7f2;
  border-top: 1px solid #eae3d6;
