  font-weight: 700;
  position: relative;
  padding-bottom: 12px;
}

.bmd-whatsIncludedTitle::after {
  content: "";
  position: absolute;
  bottom: 0;
  left: 0;
  width: 36px;
  height: 2px;
  background-color: #800000;
}

.bmd-includedList {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.bmd-includedItem {
  display: flex;
  align-items: center;
  gap: 14px;
  font-size: 14.5px;
  font-weight: 500;
  color: #293845;
}

.bmd-includedIconWrap {
  display: inline-flex;
