  height: 32px;
  border-radius: 6px;
  background-color: rgba(128, 0, 0, 0.07);
  color: #800000;
  font-size: 14px;
  flex-shrink: 0;
}

.bmd-curriculumFootnote {
  margin-top: 32px;
  font-size: 13px;
  font-style: italic;
  color: #727e8a;
  line-height: 1.6;
}

