   -------------------------------------------------------------------------- */
.bmd-instructorSection {
  padding: 80px 0;
  background-color: #ffffff;
}

.bmd-instructorCard {
  display: grid;
  grid-template-columns: 180px 1.25fr 0.75fr;
  gap: 36px;
  align-items: center;
  background-color: #ffffff;
  border: 1px solid #ebe4d8;
  border-radius: 12px;
  padding: 36px;
  box-shadow: 0 4px 20px rgba(16, 36, 58, 0.04);
}

.bmd-instructorPhotoFrame {
  position: relative;
  width: 170px;
  height: 190px;
  border-radius: 10px;
  overflow: hidden;
  box-shadow: 0 6px 18px rgba(16, 36, 58, 0.08);
  border: 1px solid #e5ded2;
}

.bmd-instructorImg {
  object-fit: cover;
  object-position: center top;
}

.bmd-instructorBioCol {
  display: flex;
  flex-direction: column;
}

.bmd-instructorName {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 1.55rem;
  color: #10243a;
  margin-bottom: 6px;
  font-weight: 700;
}

.bmd-instructorRoleTitle {
  font-size: 13.5px;
  font-weight: 700;
  color: #800000;
  margin-bottom: 4px;
  letter-spacing: 0.04em;
}

.bmd-instructorAffiliation {
  font-size: 13px;
  color: #727e8a;
  margin-bottom: 14px;
}

.bmd-instructorBioText {
  font-size: 14.5px;
  line-height: 1.65;
  color: #4e555c;
  margin: 0;
}

.bmd-expertiseCol {
  background-color: #faf7f2;
  border: 1px solid #ebe4d8;
  border-radius: 10px;
  padding: 22px 20px;
}

.bmd-expertiseHeading {
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #800000;
  margin-bottom: 14px;
}

.bmd-expertiseTagsList {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  list-style: none;
  padding: 0;
  margin: 0;
}

.bmd-expertiseTag {
  background-color: #ffffff;
  border: 1px solid #e0d8cc;
  border-radius: 4px;
  padding: 6px 12px;
  font-size: 12.5px;
  font-weight: 600;
  color: #10243a;
}

/* --------------------------------------------------------------------------
   6. WHAT LEARNERS SAY SECTION
   -------------------------------------------------------------------------- */
.bmd-testimonialsSection {
  background-color: #faf7f2;
  border-top: 1px solid #eae3d6;
  border-bottom: 1px solid #eae3d6;
  padding: 80px 0;
}

.bmd-testimonialsGrid {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 28px;
  align-items: stretch;
}

.bmd-testimonialCard {
  background-color: #ffffff;
  border: 1px solid #ebe4d8;
  border-radius: 10px;
  padding: 30px 26px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 4px 16px rgba(16, 36, 58, 0.04);
  transition: all 0.25s ease;
}

.bmd-testimonialCard:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(16, 36, 58, 0.08);
}

.bmd-quoteIcon {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 38px;
  line-height: 1;
  color: #800000;
  margin-bottom: 12px;
}

.bmd-quoteText {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 15.5px;
  line-height: 1.65;
  color: #293845;
  font-style: italic;
  margin-bottom: 20px;
  flex-grow: 1;
}

.bmd-quoteAuthor {
  font-size: 13.5px;
  font-weight: 700;
  color: #10243a;
  margin: 0;
}

.bmd-quoteRole {
  display: block;
  font-size: 12.5px;
  font-weight: 400;
  color: #727e8a;
  margin-top: 2px;
}

/* Video Testimonial Card */
.bmd-videoCardWrapper {
  background-color: #ffffff;
  border: 1px solid #ebe4d8;
  border-radius: 10px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  box-shadow: 0 4px 16px rgba(16, 36, 58, 0.04);
  cursor: pointer;
  transition: all 0.25s ease;
}

.bmd-videoCardWrapper:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(16, 36, 58, 0.08);
}

.bmd-videoThumbnailContainer {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 11;
  overflow: hidden;
  background-color: #10243a;
}

.bmd-videoThumbnailImg {
  object-fit: cover;
  transition: transform 0.4s ease;
}

.bmd-videoCardWrapper:hover .bmd-videoThumbnailImg {
  transform: scale(1.03);
}

.bmd-videoOverlayGradient {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(16, 36, 58, 0.1) 0%, rgba(16, 36, 58, 0.45) 100%);
}

.bmd-playButtonCircle {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background-color: rgba(16, 36, 58, 0.85);
  backdrop-filter: blur(4px);
  -webkit-backdrop-filter: blur(4px);
  border: 2px solid rgba(255, 255, 255, 0.85);
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.25s ease;
  box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3);
}

.bmd-videoCardWrapper:hover .bmd-playButtonCircle {
  background-color: #800000;
  border-color: #ffffff;
  transform: translate(-50%, -50%) scale(1.08);
}

.bmd-playTriangleIcon {
  margin-left: 3px;
}

.bmd-videoCardCaption {
  padding: 16px 18px;
  font-size: 13.5px;
  font-weight: 600;
  color: #10243a;
  background-color: #ffffff;
  text-align: center;
}

/* Stacked Right Quotes */
.bmd-stackedQuotesCol {
  display: flex;
  flex-direction: column;
  gap: 18px;
  justify-content: space-between;
}

.bmd-testimonialCardCompact {
  background-color: #ffffff;
  border: 1px solid #ebe4d8;
  border-radius: 10px;
  padding: 22px 24px;
  box-shadow: 0 4px 16px rgba(16, 36, 58, 0.04);
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  flex: 1;
  transition: all 0.25s ease;
}

.bmd-testimonialCardCompact:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(16, 36, 58, 0.08);
}

.bmd-quoteTextCompact {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 14.5px;
  line-height: 1.6;
  color: #293845;
  font-style: italic;
  margin-bottom: 14px;
}

.bmd-testimonialsFootnote {
  margin-top: 32px;
  font-size: 13px;
  font-style: italic;
  color: #727e8a;
  text-align: center;
}

/* --------------------------------------------------------------------------
   7. FREQUENTLY ASKED QUESTIONS SECTION
   -------------------------------------------------------------------------- */
.bmd-faqSection {
  padding: 85px 0;
  background-color: #ffffff;
}

.bmd-faqGrid {
  display: grid;
  grid-template-columns: 0.8fr 1.2fr;
  gap: 56px;
  align-items: start;
}

.bmd-faqLeftCol {
  position: sticky;
  top: 100px;
}

.bmd-faqTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(2rem, 3.2vw, 2.75rem);
  color: #10243a;
  line-height: 1.2;
  letter-spacing: -0.03em;
  margin-bottom: 16px;
  font-weight: 400;
}

.bmd-faqDescription {
  font-size: 15.5px;
  line-height: 1.7;
  color: #556473;
  margin-bottom: 28px;
}

.bmd-btnContactTeam {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background-color: transparent;
  color: #800000;
  border: 1px solid #800000;
  border-radius: 4px;
  padding: 12px 24px;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  text-decoration: none;
  transition: all 0.25s ease;
}

.bmd-btnContactTeam:hover {
  background-color: #800000;
  color: #ffffff;
}

