.bmd-faqAccordion {
  display: flex;
  flex-direction: column;
  border: 1px solid #eae3d6;
  border-radius: 12px;
  background-color: #ffffff;
  overflow: hidden;
  box-shadow: 0 4px 18px rgba(16, 36, 58, 0.04);
}

.bmd-faqItem {
  border-bottom: 1px solid #eae3d6;
  transition: background-color 0.25s ease;
}

.bmd-faqItem:last-child {
  border-bottom: none;
}

.bmd-faqItemActive {
  background-color: #faf7f2;
}

.bmd-faqQuestionButton {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 22px 28px;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
  gap: 18px;
  transition: background-color 0.2s ease;
}

.bmd-faqQuestionText {
  font-size: 16.5px;
  font-weight: 600;
  color: #10243a;
  line-height: 1.4;
  transition: color 0.2s ease;
}

.bmd-faqQuestionButton:hover .bmd-faqQuestionText,
.bmd-faqItemActive .bmd-faqQuestionText {
  color: #800000;
}

.bmd-faqToggleIcon {
  font-size: 20px;
  font-weight: 400;
  color: #800000;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.bmd-faqAnswerWrapper {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 0.3s cubic-bezier(0.4, 0, 0.2, 1);
