  grid-template-rows: 1fr;
}

.bmd-faqAnswerContent {
  min-height: 0;
  padding: 6px 28px 28px 28px;
  font-size: 15px;
  line-height: 1.75;
  color: #4e555c;
}

.bmd-faqAnswerContent p {
  margin: 0;
}

.bmd-faqAnswerNote {
  margin-top: 10px !important;
  font-size: 13.5px;
  font-style: italic;
  color: #727e8a;
  padding-top: 8px;
  border-top: 1px dashed #e8e0d4;
}

/* --------------------------------------------------------------------------
   8. READY TO BEGIN? FINAL CTA SECTION
   -------------------------------------------------------------------------- */
