    grid-column: span 2;
  }

  .bu3-fourCardsGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Tablet Portrait & Mobile (<= 768px) */
@media (max-width: 768px) {
  .bu3-heroIntroSection {
    padding: 28px 0;
  }

  .bu3-heroIntroRow {
    flex-direction: column;
  }
  .bu3-heroDecorStar {
    display: none;
  }

  .bu3-dashboardGrid {
    grid-template-columns: 1fr;
    gap: 24px;
  }

  .bu3-sidebarWrapper {
    position: static;
  }

  .bu3-mobileNavToggleWrapper {
    display: block;
  }

  .bu3-curriculumIndexCard {
    display: none;
  }

  .bu3-mobileNavExpanded {
    display: block !important;
    animation: bu3-fadeIn 0.25s ease;
  }

  .bu3-unitBanner {
    padding: 32px 24px;
  }

  .bu3-metricsStrip {
    grid-template-columns: repeat(2, 1fr);
    gap: 12px 0;
  }
  .bu3-metricCol:nth-child(2)::after {
    display: none;
  }

  .bu3-twoCardsGrid {
    grid-template-columns: 1fr;
  }

  .bu3-objectivesGrid {
    grid-template-columns: 1fr;
    gap: 10px;
  }

  .bu3-threeCardsGrid {
    grid-template-columns: 1fr;
  }
  .bu3-threeCardsGrid .bu3-resourceCard:last-child {
    grid-column: span 1;
  }

  .bu3-fourCardsGrid {
    grid-template-columns: 1fr;
  }

  .bu3-unitFooterNav {
    flex-direction: column;
    align-items: stretch;
    text-align: center;
  }
  .bu3-unitFooterLinkPrev,
  .bu3-unitFooterLinkNext {
    justify-content: center;
  }
}

/* Small Mobile (<= 480px) */
@media (max-width: 480px) {
  .bu3-heroHeading {
    font-size: 1.85rem;
  }

  .bu3-unitBannerTitle {
    font-size: 1.7rem;
  }

  .bu3-sectionHeading {
    font-size: 1.5rem;
  }

  .bu3-metricsStrip {
    grid-template-columns: 1fr;
  }
  .bu3-metricCol::after {
    display: none !important;
  }
}

@keyframes bu3-fadeIn {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }
  to {
