  text-align: center;
  display: flex;
  flex-direction: column;
  align-items: center;
  transition: all 0.25s ease;
  min-height: 210px;
}

.eb-questionCard:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 20px rgba(16, 36, 58, 0.06);
  border-color: #d0c0ac;
}

.eb-questionNumber {
  font-size: 11px;
  font-weight: 700;
  color: #8c98a4;
  letter-spacing: 0.12em;
  margin-bottom: 14px;
}

.eb-questionIconCircle {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: #800000;
  color: #ffffff;
