  align-items: center;
  justify-content: center;
  margin-bottom: 18px;
  transition: transform 0.25s ease;
}

.eb-questionCard:hover .eb-questionIconCircle {
  transform: scale(1.08);
}

.eb-questionText {
  font-size: 14.5px;
  font-weight: 600;
  color: #10243a;
  line-height: 1.45;
  margin: 0;
}

/* ==========================================================================
   5. LEARNING TO UNDERSTAND KNOWLEDGE (FRAMEWORK)
   ========================================================================== */
.eb-frameworkSection {
  padding: 76px 0 80px;
  background: #ffffff;
}

.eb-frameworkColumnsGrid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  margin-bottom: 56px;
}

.eb-frameworkCol {
  position: relative;
  padding-right: 18px;
}

.eb-frameworkCol:not(:last-child)::after {
  content: '';
  position: absolute;
  right: 0;
  top: 10px;
  bottom: 10px;
  width: 1px;
  background-color: #eae3d6;
}

.eb-frameworkTag {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #8c98a4;
  margin-bottom: 10px;
}

.eb-frameworkHeading {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 18px;
  color: #800000;
  margin-bottom: 12px;
  line-height: 1.35;
  font-weight: 700;
}

.eb-frameworkDesc {
  font-size: 14px;
  line-height: 1.65;
  color: #4e555c;
  margin: 0;
}

/* Dark Navy Connected Framework Box */
.eb-navyFrameworkPanel {
  background: #10243a;
  border-radius: 10px;
  padding: 44px 48px;
  color: #ffffff;
