  align-items: center;
  box-shadow: 0 10px 30px rgba(16, 36, 58, 0.12);
}

.eb-navyContent {
  display: flex;
  flex-direction: column;
}

.eb-navyEyebrow {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #ddb47a;
  margin-bottom: 10px;
}

.eb-navyTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(1.6rem, 2.3vw, 2.2rem);
  line-height: 1.25;
  color: #ffffff;
  margin-bottom: 16px;
  font-weight: 400;
}

.eb-navyTitleItalic {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  color: #dd7c8a;
}

.eb-navyText {
  font-size: 14.5px;
  line-height: 1.7;
  color: #b5c3d2;
