  max-width: 480px;
  height: auto;
  display: block;
}

/* ==========================================================================
   6. EXPLORE THE CURRICULUM (3x3 Grid)
   ========================================================================== */
.eb-curriculumSection {
  background-color: #faf7f2;
  border-top: 1px solid #eae3d6;
  border-bottom: 1px solid #eae3d6;
  padding: 76px 0 84px;
}

.eb-curriculumHeaderRow {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  margin-bottom: 40px;
  flex-wrap: wrap;
  gap: 16px;
}

.eb-curriculumHeaderLeft {
  max-width: 680px;
}

.eb-curriculumLinkRight {
  font-size: 12.5px;
  font-weight: 700;
  color: #800000;
  text-decoration: none;
  letter-spacing: 0.05em;
