  flex-direction: column;
  flex-grow: 1;
}

.eb-unitTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 17.5px;
  line-height: 1.35;
  color: #10243a;
  margin-bottom: 8px;
  font-weight: 700;
}

.eb-unitDesc {
  font-size: 13.5px;
  line-height: 1.6;
  color: #5c6b79;
  margin-bottom: 20px;
