}

.eb-unitFooter {
  display: flex;
  justify-content: flex-end;
  align-items: center;
  padding-top: 10px;
}

.eb-unitArrowBtn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  border: 1px solid #dcd3c5;
  background: #ffffff;
  color: #800000;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 13px;
  transition: all 0.2s ease;
}

.eb-unitCard:hover .eb-unitArrowBtn {
  background: #800000;
  color: #ffffff;
  border-color: #800000;
}

/* Audience Cards (Educators & Learners) */
.eb-audienceCard {
  background: #fbf8f3;
  border: 1px solid #e2d8c9;
  border-radius: 6px;
  padding: 30px 24px 28px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  text-align: center;
  align-items: center;
  transition: all 0.25s ease;
}

.eb-audienceCard:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 24px rgba(16, 36, 58, 0.08);
  border-color: #cbbaa5;
}

.eb-audienceIconCircle {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: #800000;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  margin-bottom: 18px;
}

.eb-audienceTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 20px;
  color: #10243a;
  margin-bottom: 10px;
  font-weight: 700;
}

.eb-audienceDesc {
  font-size: 13.5px;
  line-height: 1.65;
  color: #5c6b79;
  margin-bottom: 24px;
  max-width: 290px;
}

.eb-audienceBtn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  background-color: #800000;
  color: #ffffff !important;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 12px 20px;
  border-radius: 4px;
  text-decoration: none;
  width: 100%;
  max-width: 260px;
  transition: all 0.25s ease;
  border: 1px solid #800000;
}

.eb-audienceBtn:hover {
  background-color: #600000;
  border-color: #600000;
  transform: translateY(-1px);
}

/* ==========================================================================
   7. BUILT FOR THOUGHTFUL LEARNING
   ========================================================================== */
.eb-thoughtfulSection {
  padding: 76px 0 76px;
  background: #ffffff;
}

.eb-thoughtfulGrid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
}

.eb-thoughtfulCard {
  background: #ffffff;
  border: 1px solid #eae3d6;
  border-radius: 8px;
  padding: 34px 28px;
  transition: all 0.25s ease;
}

.eb-thoughtfulCard:hover {
  transform: translateY(-3px);
  box-shadow: 0 8px 22px rgba(16, 36, 58, 0.05);
  border-color: #d0c0ac;
}

.eb-thoughtfulIcon {
  width: 32px;
  height: 32px;
  color: #800000;
  font-size: 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 16px;
}

.eb-thoughtfulTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 19px;
  color: #10243a;
  margin-bottom: 12px;
  font-weight: 700;
}

.eb-thoughtfulDesc {
  font-size: 14.5px;
  line-height: 1.7;
  color: #4e555c;
  margin: 0;
}

/* ==========================================================================
   8. ACROSS EVERY LEARNING ENVIRONMENT
   ========================================================================== */
.eb-environmentsSection {
  padding: 76px 0 84px;
  background: #ffffff;
  border-top: 1px solid #eae3d6;
}

.eb-environmentsGrid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
}

.eb-envCard {
  background: #faf7f2;
  border: 1px solid #eae3d6;
  border-radius: 8px;
  overflow: hidden;
  display: grid;
  grid-template-columns: 210px 1fr;
  transition: all 0.25s ease;
}

.eb-envCard:hover {
  transform: translateY(-3px);
  box-shadow: 0 10px 24px rgba(16, 36, 58, 0.06);
  border-color: #d0c0ac;
}

.eb-envImageWrapper {
  position: relative;
  width: 100%;
  height: 100%;
  min-height: 175px;
  background-color: #e5e0d8;
  overflow: hidden;
}

.eb-envImage {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.eb-envContent {
  padding: 24px 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.eb-envTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 18.5px;
  color: #800000;
  margin-bottom: 8px;
  font-weight: 700;
}

.eb-envDesc {
  font-size: 14px;
  line-height: 1.65;
  color: #4e555c;
  margin: 0;
}

/* ==========================================================================
   9. LEARNER REFLECTIONS
   ========================================================================== */
.eb-reflectionsSection {
  background: #faf7f2;
  border-top: 1px solid #eae3d6;
  border-bottom: 1px solid #eae3d6;
  padding: 76px 0 84px;
}

.eb-reflectionsGrid {
  display: grid;
  grid-template-columns: 1fr 1.2fr;
  gap: 36px;
  align-items: stretch;
}

.eb-reflectionLeftPanel {
  background: linear-gradient(135deg, #6b1724 0%, #460c15 100%);
  border-radius: 8px;
  padding: 44px 38px;
  color: #ffffff;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 10px 26px rgba(107, 23, 36, 0.16);
  position: relative;
  overflow: hidden;
}

.eb-reflectionLeftPanel::before {
  content: '';
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  background-image: radial-gradient(circle at top right, rgba(255, 255, 255, 0.12), transparent 70%);
  pointer-events: none;
}

.eb-reflectionLeftEyebrow {
  font-size: 10.5px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #e5b980;
  margin-bottom: 16px;
}

.eb-reflectionLeftTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(1.75rem, 2.5vw, 2.3rem);
  line-height: 1.25;
  color: #ffffff;
  margin-bottom: 24px;
  font-weight: 400;
}

.eb-reflectionLeftLink {
  color: #ffffff;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  text-decoration: underline;
  text-underline-offset: 4px;
  transition: all 0.2s ease;
}

.eb-reflectionLeftLink:hover {
  color: #e5b980;
}

.eb-reflectionRightCard {
  background: #ffffff;
  border: 1px solid #eae3d6;
  border-radius: 8px;
  padding: 44px 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  position: relative;
}

.eb-quoteMark {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 64px;
  line-height: 1;
  color: #800000;
  margin-bottom: -10px;
}

.eb-reflectionQuote {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-style: italic;
  font-size: clamp(1.2rem, 1.8vw, 1.45rem);
  line-height: 1.5;
  color: #10243a;
  margin-bottom: 24px;
  font-weight: 400;
}

.eb-reflectionAuthor {
  font-size: 13.5px;
  font-weight: 700;
  color: #10243a;
  margin-bottom: 4px;
}

.eb-reflectionSource {
  font-size: 12.5px;
  color: #72808e;
}

/* ==========================================================================
   10. PARTNERS & SUPPORT
   ========================================================================== */
.eb-partnersSection {
  padding: 76px 0 80px;
  background: #ffffff;
}

.eb-partnersWrapper {
  max-width: 720px;
  margin: 0 auto;
}

.eb-partnersTabButtons {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-bottom: 20px;
}

.eb-partnerTabBtn {
  background: #ffffff;
  border: 1px solid #d5c8b5;
  color: #4e555c;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  padding: 11px 26px;
  border-radius: 4px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.eb-partnerTabBtn:hover {
  border-color: #800000;
  color: #800000;
}

.eb-partnerTabBtnActive {
  background: #800000;
  border-color: #800000;
  color: #ffffff !important;
}

.eb-partnersContentCard {
  background: #faf7f2;
  border: 1px solid #eae3d6;
  border-radius: 6px;
  padding: 32px 36px;
  text-align: center;
}

.eb-partnerTabPanel {
  animation: eb-fadeIn 0.3s ease;
}

.eb-partnerText {
  font-size: 14.5px;
  line-height: 1.7;
  color: #4e555c;
  margin-bottom: 16px;
}

.eb-partnerLink {
  color: #800000;
  font-size: 12.5px;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-decoration: underline;
  text-underline-offset: 4px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  transition: color 0.2s ease;
}

.eb-partnerLink:hover {
  color: #600000;
}

/* ==========================================================================
   11. FREQUENTLY ASKED QUESTIONS
   ========================================================================== */
.eb-faqSection {
  padding: 76px 0 96px;
  background: #ffffff;
  border-top: 1px solid #eae3d6;
}

.eb-faqGrid {
  display: grid;
  grid-template-columns: 0.85fr 1.15fr;
  gap: 48px;
  align-items: start;
}

.eb-faqTitle {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(2.2rem, 3.4vw, 3rem);
  line-height: 1.15;
  color: #10243a;
  margin-bottom: 18px;
  font-weight: 400;
}

.eb-faqDesc {
  font-size: 15px;
  line-height: 1.65;
  color: #5c6b79;
}

.eb-faqAccordion {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.eb-faqItem {
  background: #ffffff;
  border: 1px solid #eae3d6;
  border-radius: 6px;
  overflow: hidden;
  transition: all 0.2s ease;
}

.eb-faqItemOpen {
  background: #faf7f2;
  border-color: #d8cdbe;
}

.eb-faqQuestionBtn {
  width: 100%;
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  background: transparent;
  border: none;
  cursor: pointer;
  text-align: left;
  transition: all 0.2s ease;
}

.eb-faqQuestionText {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 16px;
  line-height: 1.4;
  color: #10243a;
  font-weight: 400;
}

.eb-faqItemOpen .eb-faqQuestionText {
  color: #800000;
}

.eb-faqChevron {
  color: #72808e;
  transition: transform 0.25s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.eb-faqChevronOpen {
  transform: rotate(180deg);
  color: #800000;
}

.eb-faqAnswerWrapper {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s cubic-bezier(0, 1, 0, 1);
}

.eb-faqAnswerVisible {
  max-height: 500px;
  transition: max-height 0.35s ease-in-out;
}

.eb-faqAnswerContent {
  padding: 0 22px 20px;
}

.eb-faqAnswerContent p {
  font-size: 14px;
  line-height: 1.7;
  color: #4e555c;
  margin: 0;
}

/* ==========================================================================
   ANIMATIONS & KEYFRAMES
   ========================================================================== */
@keyframes eb-fadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* ==========================================================================
   RESPONSIVE BREAKPOINTS
   ========================================================================== */

/* Tablet Landscape / Small Desktop (<= 1024px) */
@media (max-width: 1024px) {
  .eb-heroRow {
    flex-direction: column;
  }
  .eb-heroContentCol {
    padding: 48px 0 36px 0;
  }
  .eb-heroImageCol {
    min-height: 420px;
  }
  .eb-heroImageWrapper {
    min-height: 420px;
  }

  .eb-overviewGrid {
    grid-template-columns: 1fr;
    gap: 36px;
  }

  .eb-fiveQuestionsRow {
    grid-template-columns: repeat(3, 1fr);
  }
  .eb-questionCard:last-child {
    grid-column: span 2;
  }

  .eb-frameworkColumnsGrid {
    grid-template-columns: repeat(2, 1fr);
    gap: 28px;
  }
  .eb-frameworkCol::after {
    display: none;
  }

  .eb-navyFrameworkPanel {
    grid-template-columns: 1fr;
    gap: 32px;
    padding: 36px 30px;
  }

  .eb-curriculumGrid {
    grid-template-columns: repeat(2, 1fr);
  }

  .eb-environmentsGrid {
    grid-template-columns: 1fr;
  }

  .eb-reflectionsGrid {
    grid-template-columns: 1fr;
    gap: 28px;
  }

  .eb-faqGrid {
    grid-template-columns: 1fr;
    gap: 32px;
  }
}

/* Tablet Portrait (<= 768px) */
@media (max-width: 768px) {
  .eb-stickySubnav {
    top: 72px;
  }
  .eb-subnavLink {
    padding: 12px 10px;
    font-size: 11px;
  }

  .eb-heroTitle {
    font-size: 2.3rem;
  }
  .eb-heroSubtitle {
    font-size: 1.15rem;
  }
  .eb-heroBtnGroup {
    flex-direction: column;
    align-items: stretch;
  }
  .eb-btnBurgundy, .eb-btnOutline {
    width: 100%;
    text-align: center;
  }

  .eb-fiveQuestionsRow {
    grid-template-columns: repeat(2, 1fr);
  }
  .eb-questionCard:last-child {
    grid-column: span 2;
  }

  .eb-frameworkColumnsGrid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .eb-curriculumGrid {
    grid-template-columns: 1fr;
  }

  .eb-thoughtfulGrid {
    grid-template-columns: 1fr;
    gap: 20px;
  }

  .eb-envCard {
    grid-template-columns: 1fr;
  }
  .eb-envImageWrapper {
    height: 180px;
  }

  .eb-reflectionLeftPanel {
    padding: 32px 24px;
  }
  .eb-reflectionRightCard {
    padding: 32px 24px;
  }
}

/* Mobile (<= 480px) */
@media (max-width: 480px) {
  .eb-heroTitle {
    font-size: 1.95rem;
  }
  .eb-heroSubtitle {
    font-size: 1.05rem;
  }
  .eb-heroLead {
    font-size: 14.5px;
  }
  .eb-heroImageCol {
    min-height: 360px;
  }
  .eb-heroImageWrapper {
    min-height: 360px;
  }

  .eb-overviewHeading {
    font-size: clamp(1.4rem, 5.5vw, 1.85rem);
    word-break: normal;
    overflow-wrap: normal;
    hyphens: none;
  }
  .eb-overviewCard {
    padding: 24px 18px;
  }

  .eb-sectionTitle {
    font-size: 1.75rem;
  }

  .eb-fiveQuestionsRow {
    grid-template-columns: 1fr;
  }
  .eb-questionCard:last-child {
    grid-column: span 1;
  }

  .eb-navyFrameworkPanel {
    padding: 26px 18px;
  }
  .eb-navyTitle {
    font-size: 1.5rem;
  }

  .eb-partnersTabButtons {
