  width: 100%;
  max-width: 360px;
  aspect-ratio: 16 / 9;
  height: auto;
  min-height: 160px;
}

.symp-speakersGrid--2 .symp-videoThumbWrap {
  width: 100%;
  aspect-ratio: 16 / 9;
  height: auto;
  min-height: 150px;
