  width: 100%;
  padding: 9px 15px;
  border-radius: 6px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  background-color: #ffffff;
  color: #1e293b;
  font-size: 13.5px;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.symp-newsletter-input:focus {
  border-color: #0b1b3d;
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.4);
}

.symp-newsletter-btn {
  padding: 9px 20px;
  background-color: #5e131b;
  border: 1px solid rgba(255, 255, 255, 0.6);
  border-radius: 6px;
  color: #ffffff;
  font-size: 13.5px;
  font-weight: 600;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
  white-space: nowrap;
}

.symp-newsletter-btn:hover {
  background-color: #4a0d14;
  border-color: #ffffff;
}

.symp-newsletter-success {
  display: flex;
  align-items: center;
  font-size: 13.5px;
  font-weight: 600;
  color: #ffffff;
  background: rgba(255, 255, 255, 0.15);
  padding: 8px 16px;
  border-radius: 6px;
}

/* 6. MODALS & LIGHTBOXES */
.symp-modalBackdrop {
  position: fixed;
  inset: 0;
  z-index: 9999;
  background: rgba(11, 27, 61, 0.85);
  backdrop-filter: blur(6px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: sympFadeIn 0.25s ease;
}

.symp-modalDialog {
  position: relative;
  width: 100%;
  max-width: 820px;
  background: #ffffff;
  border-radius: 12px;
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.35);
  animation: sympSlideUp 0.25s ease;
}

.symp-modalClose {
  position: absolute;
  top: 14px;
  right: 14px;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.6);
  border: none;
  color: #ffffff;
  font-size: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  z-index: 10;
  transition: background 0.2s ease;
}

.symp-modalClose:hover {
  background: #781d2a;
}

.symp-modalVideoWrap {
  position: relative;
  width: 100%;
  padding-bottom: 56.25%;
  background: #000;
}

.symp-modalIframe {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  border: none;
}

.symp-modalInfo {
  padding: 22px 28px;
  background: #ffffff;
}

.symp-modalEyebrow {
  display: inline-block;
  font-size: 11.5px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: #8b2131;
  text-transform: uppercase;
  margin-bottom: 6px;
}

.symp-modalTitle {
  font-family: var(--font-libre), 'Libre Baskerville', Georgia, serif;
  font-size: 20px;
  font-weight: 700;
  color: #0b1b3d;
  margin: 0 0 6px 0;
}

.symp-modalSpeaker {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.symp-modalYtBtn {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  font-size: 13px;
  font-weight: 600;
  color: #c4302b;
  background: #fdf2f2;
  border: 1px solid #fecaca;
  border-radius: 9999px;
  padding: 8px 16px;
  text-decoration: none;
  transition: all 0.2s ease;
  margin-top: 4px;
}

.symp-modalYtBtn:hover {
  background: #c4302b;
  color: #ffffff;
  border-color: #c4302b;
  box-shadow: 0 4px 12px rgba(196, 48, 43, 0.25);
}

/* Brochure Modal Specifics */
.symp-brochureDialog {
  max-width: 740px;
  max-height: 85vh;
  overflow-y: auto;
}

.symp-brochureContent {
  padding: 34px 38px;
}

.symp-brochureHeader {
  border-bottom: 2px solid #8b2131;
  padding-bottom: 18px;
  margin-bottom: 24px;
}

.symp-brochureTitle {
  font-family: var(--font-libre), 'Libre Baskerville', Georgia, serif;
  font-size: 26px;
  font-weight: 700;
  color: #0b1b3d;
  margin: 10px 0;
}

.symp-brochureMeta {
  font-size: 14px;
  color: #64748b;
  margin: 0;
}

.symp-brochureSection {
  margin-bottom: 22px;
}

.symp-brochureSection h4 {
  font-size: 16px;
  font-weight: 700;
  color: #0b1b3d;
  margin-bottom: 8px;
}

.symp-brochureSection p {
  font-size: 14.5px;
  line-height: 1.6;
  color: #334155;
}

.symp-brochureSchedule {
  list-style: none;
  padding-left: 0;
  margin: 0;
}

.symp-brochureSchedule li {
  position: relative;
  padding-left: 18px;
  margin-bottom: 10px;
  font-size: 14px;
  line-height: 1.5;
  color: #334155;
}

.symp-brochureSchedule li::before {
  content: "•";
  position: absolute;
  left: 0;
  color: #8b2131;
  font-size: 18px;
  line-height: 1;
}

.symp-brochureActions {
  display: flex;
  align-items: center;
  margin-top: 28px;
  padding-top: 18px;
  border-top: 1px solid #f0eae1;
}

@keyframes sympFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes sympSlideUp {
  from { transform: translateY(16px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

/* ==========================================================================
   RESPONSIVE DESIGN BREAKPOINTS
   ========================================================================== */

/* Tablet & Smaller Desktops (991px and down) */
@media (max-width: 991.98px) {
  .symp-hero-container {
    padding-top: 36px;
    padding-bottom: 36px;
  }

  .symp-hero-copyCol {
    padding-right: 0;
    margin-bottom: 28px;
  }

  .symp-hero-title {
    font-size: 32px;
  }

  .symp-overview-card {
    flex-direction: column;
    align-items: flex-start;
    gap: 16px;
  }

  .symp-overview-titleCol {
    flex: none;
    width: 100%;
  }

  .symp-overview-divider {
    display: none;
  }

  /* Single row adjustments */
  .symp-singleRow .symp-cardSpeakerCol {
    margin-top: 10px;
  }

  .symp-singleRow .symp-videoThumbWrap {
    max-width: 100%;
    min-height: 180px;
  }

  .symp-speakersGrid--3 {
    grid-template-columns: repeat(2, 1fr);
  }

  .symp-singleRow .symp-speakerDetails {
    padding-left: 0;
  }

  /* Newsletter wrap */
  .symp-newsletter-box {
    flex-direction: column;
    align-items: flex-start;
    gap: 22px;
  }

  .symp-newsletter-right {
    width: 100%;
  }

  .symp-newsletter-form {
    width: 100%;
  }

  .symp-newsletter-inputWrap {
    flex: 1;
    width: auto;
  }
}

/* Small Tablets / Large Phones (767px and down) */
@media (max-width: 767.98px) {
  .symp-hero-title {
    font-size: 28px;
  }

  .symp-hero-meta {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .symp-hero-meta-divider {
    display: none;
  }

  .symp-singleRow .symp-videoThumbWrap {
    width: 100%;
    aspect-ratio: 16 / 9;
    height: auto;
    min-height: 160px;
    max-width: 100%;
  }

  .symp-speakersGrid--2,
  .symp-speakersGrid--3 {
    grid-template-columns: 1fr;
    gap: 18px;
  }

  .symp-speakersGrid--2 .symp-videoThumbWrap,
  .symp-speakersGrid--3 .symp-videoThumbWrap {
    width: 100%;
    aspect-ratio: 16 / 9;
    height: auto;
    min-height: 160px;
  }

  .symp-sessionCard {
    padding: 18px 16px;
  }

  .symp-cardTitle {
    font-size: 18px;
    margin-bottom: 12px;
  }

  .symp-sponsors-inner {
    flex-direction: column;
    gap: 22px;
    text-align: center;
  }

  .symp-sponsors-titleWrap {
    justify-content: center;
  }

  .symp-sponsors-rule {
    display: none;
  }

  .symp-sponsors-title {
    justify-content: center;
  }

  .symp-sponsors-list {
    flex-direction: column;
    gap: 18px;
  }

  .symp-sponsor-group {
    flex-direction: column;
    gap: 18px;
  }

  .symp-sponsor-divider {
    width: 44px;
    height: 1px;
  }

  .symp-newsletter-left {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }

  .symp-newsletter-divider {
    display: none;
  }

  .symp-newsletter-form {
    flex-direction: column;
    align-items: stretch;
    gap: 12px;
  }

  .symp-newsletter-btn {
    width: 100%;
  }

  .symp-brochureContent {
    padding: 24px 20px;
  }
}

/* Extra Small Mobile (390px and down) */
@media (max-width: 390px) {
  .symp-hero-title {
    font-size: 24px;
  }

  .symp-overview-heading {
    font-size: 24px;
  }

  .symp-cardTitle {
    font-size: 16px;
  }

  .symp-hero-btn {
    width: 100%;
  }
}



