/* ==========================================================================
   DONATION MODAL POPUP (ZEFFY)
   ========================================================================== */

.donation-modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 999999;
  background: rgba(12, 22, 33, 0.72);
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: donationFadeIn 0.22s ease-out;
}

@keyframes donationFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.donation-modal-container {
  background: #ffffff;
  width: 100%;
  max-width: 660px;
  height: 90vh;
  max-height: 820px;
  border-radius: 14px;
  box-shadow: 0 25px 65px -15px rgba(0, 0, 0, 0.45), 0 0 0 1px rgba(0, 0, 0, 0.08);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  position: relative;
  animation: donationSlideUp 0.28s cubic-bezier(0.16, 1, 0.3, 1);
}

@keyframes donationSlideUp {
  from {
    opacity: 0;
    transform: translateY(24px) scale(0.97);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

.donation-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 18px 24px 14px;
  background: linear-gradient(180deg, #faf7f2 0%, #ffffff 100%);
  border-bottom: 1px solid #ede7db;
  gap: 16px;
}

.donation-modal-badge {
  display: inline-flex;
  align-items: center;
  background: rgba(128, 0, 0, 0.08);
  color: #800000;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  padding: 3px 8px;
  border-radius: 4px;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.donation-modal-badge i {
  color: #800000;
  font-size: 10px;
}

.donation-modal-title {
  font-family: "Libre Baskerville", serif;
  font-size: 20px;
  font-weight: 700;
  color: #10243a;
  margin: 0 0 4px 0;
  line-height: 1.25;
}

.donation-modal-subtitle {
  font-family: "DM Sans", sans-serif;
  font-size: 12px;
  color: #556270;
  margin: 0;
  line-height: 1.4;
}

.donation-modal-close {
  background: #f1edec;
  border: none;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #444;
  font-size: 15px;
  cursor: pointer;
  transition: all 0.18s ease;
  flex-shrink: 0;
}

.donation-modal-close:hover {
  background: #800000;
  color: #ffffff;
  transform: rotate(90deg);
}

.donation-modal-body {
  flex: 1;
  position: relative;
  width: 100%;
  height: 100%;
  background: #ffffff;
  overflow: hidden;
}

.donation-modal-loader {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  background: #ffffff;
  gap: 14px;
  color: #556270;
  font-family: "DM Sans", sans-serif;
  font-size: 13.5px;
  z-index: 1;
}

.donation-modal-spinner {
  width: 38px;
  height: 38px;
  border: 3px solid rgba(128, 0, 0, 0.15);
  border-top-color: #800000;
  border-radius: 50%;
  animation: donationSpin 0.75s linear infinite;
}

@keyframes donationSpin {
  to {
    transform: rotate(360deg);
  }
}

.donation-modal-iframe {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  border: 0;
  opacity: 1;
  transition: opacity 0.2s ease;
}

.donation-modal-iframe--hidden {
  opacity: 0;
}

.donation-modal-footer {
  padding: 10px 20px;
  background: #faf8f5;
  border-top: 1px solid #ede7db;
  text-align: center;
  font-family: "DM Sans", sans-serif;
  font-size: 11.5px;
  color: #6a7480;
}

@media (max-width: 576px) {
  .donation-modal-container {
    height: 94vh;
    max-height: 94vh;
    border-radius: 12px;
  }
  .donation-modal-header {
    padding: 14px 16px 12px;
  }
  .donation-modal-title {
    font-size: 18px;
  }
}


