}

.fc-lightbox-backdrop {
  position: fixed;
  inset: 0;
  z-index: 9999999;
  background: rgba(8, 16, 26, 0.94);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px;
  animation: fcLightboxFadeIn 0.2s ease-out;
}

@keyframes fcLightboxFadeIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}

.fc-lightbox-toolbar {
  position: absolute;
  top: 16px;
  left: 20px;
  right: 20px;
