  box-shadow: 0 6px 32px rgba(0,0,0,0.13);
  transform: translateY(-2px);
}
.conf-card:nth-child(even) {
  grid-template-columns: 1fr 380px;
}
.conf-card:nth-child(even) .conf-card-media {
  order: 2;
}
.conf-card:nth-child(even) .conf-card-body {
  order: 1;
}
.conf-card-media {
