/* RESPONSIVE */
@media (max-width: 1100px) {
  .conf-card { grid-template-columns: 1fr 400px; }
  .conf-card:nth-child(even) { grid-template-columns: 400px 1fr; }
  .conf-card-body { padding: 40px 40px 40px 44px; }
  .conf-card:nth-child(even) .conf-card-body { padding: 40px 44px 40px 40px; }
}
@media (max-width: 860px) {
  .conf-stats-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 20px 32px;
  }
  .conf-card,
  .conf-card:nth-child(even) {
    grid-template-columns: 1fr;
  }
  .conf-card:nth-child(even) .conf-card-media {
    order: 0;
  }
  .conf-card-media { min-height: 240px; }
  .conf-card-media img { min-height: 240px; max-height: 300px; }
  .conf-card-body,
  .conf-card:nth-child(even) .conf-card-body {
    padding: 32px 28px;
    border-left: 4px solid #800000 !important;
    border-right: none !important;
  }
  .conf-card-num { top: 14px; right: 16px; font-size: 3.5rem; }
  .conf-card:nth-child(even) .conf-card-num { left: auto; right: 16px; }
}
@media (max-width: 540px) {
  .conf-stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  /* conf hero handled by hero-seamless responsive */
  .conf-cta-actions {
    flex-direction: column;
    align-items: center;
  }
}

