/* =========================================================
   EMPART TEAM SLIDER
   ========================================================= */
.empart-team-slider {
  margin-top: 40px;
  padding: 0 8px;
}
.empart-team-track-wrap {
  overflow: hidden;
  padding: 12px 4px 16px;
}
.empart-team-track {
  display: flex;
  gap: 32px;
}
.empart-team-slide {
  flex: 0 0 calc((100% - 32px * 4) / 5);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 14px;
}
.empart-team-circle {
  width: 150px;
  height: 150px;
  border-radius: 50%;
  overflow: hidden;
  border: 4px solid #e2c48a;
  box-shadow: 0 4px 20px rgba(0,0,0,0.13);
  transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;
  background: #f0ece6;
}
.empart-team-circle:hover {
  transform: translateY(-6px) scale(1.04);
  box-shadow: 0 12px 32px rgba(90,30,20,0.18);
  border-color: #7a2520;
}
.empart-team-circle img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center top;
  display: block;
}
/* Dot indicators — override existing */
.empart-team-slider .empart-paginationDots {
  display: flex;
  justify-content: center;
  gap: 8px;
  margin-top: 20px;
}
.empart-team-slider .empart-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ccc;
  display: inline-block;
  transition: background 0.25s, transform 0.25s, width 0.25s;
  border: none;
}
.empart-team-slider .empart-dot.active {
  background: #7a2520;
  transform: scale(1.4);
  width: 20px;
  border-radius: 10px;
}
@media (max-width: 900px) {
  .empart-team-slide {
    flex: 0 0 calc((100% - 32px * 2) / 3);
  }
}
@media (max-width: 560px) {
  .empart-team-slide {
    flex: 0 0 calc((100% - 32px) / 2);
  }
  .empart-team-circle {
    width: 120px;
    height: 120px;
  }
}

