/* --------------------------------------------------------------------------
   7. GOHIGHLEVEL POPUP MODAL
   -------------------------------------------------------------------------- */
.ev-modal-overlay {
  position: fixed;
  inset: 0;
  background-color: rgba(16, 36, 58, 0.72);
  backdrop-filter: blur(4px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  animation: evFadeIn 0.25s ease;
}

.ev-modal-dialog {
  background-color: #ffffff;
  border-radius: 8px;
  width: 100%;
  max-width: 680px;
  max-height: 90vh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.3);
  animation: evScaleUp 0.25s ease;
}

.ev-modal-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 24px;
  border-bottom: 1px solid #ebd9c8;
  background-color: #fbf8f4;
}

.ev-modal-eyebrow {
  font-family: 'DM Sans', sans-serif;
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: #800000;
  text-transform: uppercase;
  display: block;
  margin-bottom: 2px;
}

.ev-modal-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 18px;
  font-weight: 700;
  color: #10243a;
  margin: 0;
}

.ev-modal-close {
  background: transparent;
  border: none;
  color: #5c6773;
  font-size: 20px;
  cursor: pointer;
  width: 36px;
  height: 36px;
  border-radius: 4px;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: color 0.2s, background-color 0.2s;
}

.ev-modal-close:hover {
  color: #800000;
  background-color: #eee5db;
}

.ev-modal-body {
  flex-grow: 1;
  position: relative;
  min-height: 480px;
  overflow-y: auto;
  -webkit-overflow-scrolling: touch;
}

.ev-modal-iframe {
  width: 100%;
  height: 100%;
  min-height: 520px;
  border: none;
  display: block;
}

.ev-modal-loader {
  position: absolute;
  inset: 0;
  background-color: #ffffff;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 14px;
  color: #5c6773;
  font-family: 'DM Sans', sans-serif;
  font-size: 13.5px;
}

.ev-modal-spinner {
  width: 38px;
  height: 38px;
  border: 3px solid #ebd9c8;
  border-top-color: #800000;
  border-radius: 50%;
  animation: evSpin 0.8s linear infinite;
}

@keyframes evFadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes evScaleUp {
  from { opacity: 0; transform: scale(0.96); }
  to { opacity: 1; transform: scale(1); }
}

@keyframes evSpin {
  to { transform: rotate(360deg); }
}

/* --------------------------------------------------------------------------
   8. RESPONSIVE BREAKPOINTS (Award-Winning Cleanliness)
   -------------------------------------------------------------------------- */
@media (max-width: 1199px) {
  .ev-hero-card {
    grid-template-columns: 52% 48%;
  }
  .ev-categories-grid {
    gap: 12px;
  }
  .ev-cat-card {
    padding: 22px 14px 20px;
  }
  .ev-past-row {
    grid-template-columns: 180px 1fr auto;
    gap: 18px;
  }
}

@media (max-width: 991px) {
  .ev-hero-card {
    grid-template-columns: 1fr;
  }
  .ev-hero-media {
    min-height: 300px;
    height: 300px;
    order: 2;
  }
  .ev-hero-copy {
    order: 1;
    padding: 40px 32px 36px;
  }
  .ev-hero-gradient-overlay {
    background: linear-gradient(to bottom, #fbf8f4 0%, rgba(251, 248, 244, 0.4) 25%, transparent 60%);
  }
  .ev-categories-section {
    margin-top: -36px;
    padding: 0 0 48px;
  }
  .ev-categories-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 14px;
  }
  .ev-featured-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .ev-register-card {
    grid-template-columns: 1fr;
  }
  .ev-register-media {
    height: 240px;
    min-height: 240px;
  }
  .ev-register-content {
    padding: 36px 32px;
  }
  .ev-newsletter-card {
    flex-direction: column;
    align-items: flex-start;
    gap: 22px;
  }
  .ev-newsletter-right {
    max-width: 100%;
  }
}

@media (max-width: 767px) {
  .ev-hero-section {
    padding-top: 20px;
  }
  .ev-hero-copy {
    padding: 32px 20px 28px;
  }
  .ev-hero-media {
    height: 240px;
    min-height: 240px;
  }
  .ev-categories-section {
    margin-top: -24px;
    padding: 0 0 40px;
  }
  .ev-featured-section,
  .ev-past-section,
  .ev-register-section {
    padding-bottom: 48px;
  }
  .ev-featured-body {
    padding: 18px;
    gap: 14px;
  }
  .ev-past-row {
    grid-template-columns: 1fr;
    padding: 16px;
    gap: 14px;
  }
  .ev-past-thumb-wrap {
    max-height: 160px;
  }
  .ev-past-action {
    display: flex;
  }
  .ev-past-btn {
    width: 100%;
    justify-content: center;
  }
  .ev-register-content {
    padding: 28px 20px;
  }
  .ev-register-btn {
    width: 100%;
    justify-content: center;
  }
  .ev-newsletter-section {
    padding: 30px 0;
  }
  .ev-newsletter-left {
    flex-direction: column;
    align-items: flex-start;
    gap: 12px;
  }
  .ev-newsletter-field-group {
    flex-direction: column;
    padding: 4px;
    gap: 8px;
  }
  .ev-newsletter-input {
    width: 100%;
  }
  .ev-newsletter-btn {
    width: 100%;
    justify-content: center;
  }
}

@media (max-width: 480px) {
  .ev-categories-grid {
    grid-template-columns: 1fr;
  }
  .ev-cat-card {
    padding: 18px 16px;
  }
  .ev-featured-body {
    flex-direction: column;
  }
  .ev-date-badge {
    flex-direction: row;
    gap: 8px;
    width: 100%;
    padding: 6px 12px;
  }
  .ev-date-day {
    margin: 0;
    font-size: 20px;
  }
  .ev-featured-action {
    width: 100%;
  }
  .ev-featured-btn {
    width: 100%;
    justify-content: center;
  }
}

