/* CONF LIST — updated background */
.conf-list {
  background: #f9f7f4 !important;
}

/* CARD NUM badge */
.conf-card-num {
  display: none;
}

/* QUOTE BANNER */
.conf-quote-section {
  background: #800000;
  padding: 56px 0;
}
.conf-quote-inner {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}
.conf-quote-mark {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: 5rem;
  line-height: 0.6;
  color: rgba(255,255,255,0.3);
  display: block;
  margin-bottom: 16px;
}
.conf-quote-text {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(1.1rem, 2vw, 1.4rem);
  font-style: italic;
  color: #fff;
  line-height: 1.6;
  margin-bottom: 20px;
}
.conf-quote-attr {
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.65);
}

/* CTA — updated with bg image */
.conf-cta {
  position: relative !important;
  overflow: hidden;
}
/* conf-cta button overrides */
.conf-cta .btn-seamless-outline {
  color: rgba(255,255,255,0.9);
  border-color: rgba(255,255,255,0.4);
}
.conf-cta .btn-seamless-outline:hover {
  color: #fff;
  border-color: #fff;
  background: rgba(255,255,255,0.1);
}
.conf-cta-bg {
  position: absolute;
  inset: 0;
}
.conf-cta-bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}
.conf-cta-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, rgba(58,34,22,0.93) 50%, rgba(58,34,22,0.75) 100%);
}
.conf-cta-inner {
  position: relative;
  z-index: 1;
  max-width: 680px;
}
.conf-cta-title {
  font-family: 'Libre Baskerville', Georgia, serif;
  font-size: clamp(1.6rem, 2.5vw, 2.2rem);
  font-weight: 700;
  color: #fff;
  margin: 12px 0 16px;
}
.conf-cta-lead {
  font-size: 1rem;
  color: rgba(255,255,255,0.85);
  line-height: 1.65;
  margin-bottom: 0;
}

/* Responsive */
@media (max-width: 900px) {
  .conf-pillars-grid { grid-template-columns: 1fr; gap: 20px; }
}
@media (max-width: 768px) {
  /* conf hero actions handled by hero-seamless */
  .conf-pillars-grid { grid-template-columns: 1fr; }
}


